insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f048','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','By Gibbs'' phase rule F = C - P + 2, the Al2SiO5 triple point is invariant (F = 0), a boundary between two polymorphs is univariant (F = 1) and a single-polymorph field is divariant (F = 2).','C = 1 component here. F is the number of things (P, T) we can change freely without losing a phase.','IIT-JAM Geology 2019',true,3,1,1253) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f049','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','Goldschmidt''s mineralogical phase rule states that in a rock at equilibrium the number of mineral phases cannot exceed the number of components (P ≤ C).','A rock normally forms over a range of P and T, so F is at least 2. Put F ≥ 2 into F = C - P + 2 and P ≤ C follows.',null,true,3,1,1254) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f050','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','In Eskola''s ACF diagram, A = Al2O3 + Fe2O3 - (Na2O + K2O), C = CaO (corrected for apatite) and F = FeO + MgO + MnO; quartz is assumed in excess.','It squeezes rock chemistry into a triangle. It works best for basic and calcareous rocks.','UPSC Geologist Mains 2020 Geology Paper II (descriptive)',true,3,1,1255) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f051','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','In the AKF diagram, A = Al2O3 + Fe2O3 - (Na2O + K2O + CaO), K = K2O and F = FeO + MgO + MnO; it is used for potassium-bearing pelitic rocks.','ACF cannot show muscovite, biotite and K-feldspar. AKF gives potassium its own corner.',null,true,2,2,1256) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f052','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','Thompson''s AFM diagram (1957) for pelites is projected from muscovite: A = Al2O3 - 3K2O, F = FeO, M = MgO (from K-feldspar at high grade, A = Al2O3 - K2O).','ACF and AKF lump FeO and MgO together. AFM separates them, so it shows iron-magnesium differences between garnet, biotite, staurolite and chlorite.',null,true,3,1,1257) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f053','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Contact metamorphism of pelitic rocks gives, towards the intrusion, spotted slate and then andalusite-cordierite hornfels; sillimanite and K-feldspar may appear at the inner contact.','Spots are early clots of cordierite, andalusite or carbon. Low pressure in aureoles favours andalusite and cordierite.',null,true,3,1,1258) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f054','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Chiastolite is a variety of andalusite with dark carbonaceous inclusions arranged in a cross; it is typical of contact-metamorphosed carbon-rich slates.','Chi is the Greek letter X. The cross is seen in the square cross-section of the crystal.',null,true,2,2,1259) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f055','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Skarn (tactite) is a calc-silicate rock formed by metasomatism where a granitic intrusion meets limestone or dolomite; typical minerals are grossular-andradite garnet, diopside-hedenbergite and wollastonite.','Hot fluids from the magma add silica, iron and aluminium to the carbonate rock. Skarns host ores of tungsten (scheelite), copper, iron and tin.','IIT-JAM Geology 2020',true,3,1,1260) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f056','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','In siliceous limestone at high temperature, calcite + quartz react to wollastonite + CO2 (CaCO3 + SiO2 = CaSiO3 + CO2).','This is a decarbonation reaction (CO2 is driven off). If CO2 cannot escape, the reaction needs a higher temperature.',null,true,3,1,1261) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f057','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','One common order in siliceous dolomite: talc, tremolite, diopside, forsterite, wollastonite, periclase, monticellite. Bowen''s list differs: tremolite, forsterite, diopside, periclase, wollastonite, monticellite.','Each step drives off more CO2 (decarbonation). Order of forsterite/diopside and of periclase/wollastonite depends on rock and fluid composition and on the textbook. Talc and tremolite always come first. Rare top-end minerals: spurrite, merwinite, larnite.','Kerala PSC HSST Geology 2026 (paper 80/2026)',false,3,1,1262) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f058','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','At high temperature and low pressure, dolomite breaks down to periclase + calcite + CO2 (dedolomitisation); periclase later hydrates to brucite, giving brucite marble.','Periclase is MgO. It takes up water easily on cooling, so we usually see brucite, Mg(OH)2, instead.',null,true,2,2,1263) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f059','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Regional metamorphism of impure limestone or marl gives calc-silicate rocks with tremolite, diopside, grossular garnet, epidote-zoisite, scapolite and calcic plagioclase.','Clay and silica impurities react with calcite and dolomite. A pure limestone would give only marble.','IIT-JAM Geology 2019',true,2,2,1264) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f060','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Metasomatism is metamorphism with a marked change in bulk chemical composition, caused by fluids that add and remove material while the rock remains solid.','Ordinary metamorphism is nearly isochemical (same chemistry, except loss of water and CO2). Metasomatism is not.','UPSC Geologist Exam 2018 Geology Paper II (descriptive)',true,3,1,1265) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f061','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Korzhinskii recognised two types of metasomatism: infiltration metasomatism (material carried by flowing fluid) and diffusion metasomatism (material moving through stationary pore fluid).','Infiltration works over long distances along fractures. Diffusion works only over centimetres to metres at contacts.',null,true,2,2,1266) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f062','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Fenitisation is alkali (sodium-potassium) metasomatism of country rocks around carbonatite and alkaline intrusions; the product is fenite, named after Fen in Norway.','Alkali-rich fluids leave the carbonatite magma and soak the wall rocks. Fenite is a field guide to hidden carbonatites.',null,true,3,1,1267) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f063','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Greisenisation changes granite to greisen, a quartz + white mica rock with topaz, tourmaline or fluorite, by fluorine-rich fluids; it is linked with tin and tungsten ores.','Feldspar is destroyed by the acid, fluorine-bearing late fluids (pneumatolysis = alteration by hot gases).',null,true,2,2,1268) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f064','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Other metasomatic changes are serpentinisation of ultramafic rocks, spilitisation (soda added to basalt, giving albite) and rodingite formation (calcium added to rocks within serpentinite).','Each is named by what is added: water, sodium or calcium.',null,true,1,3,1269) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f065','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Granitization is the conversion of pre-existing solid rocks into granite-like rock by metasomatism, without passing through a magma stage.','It was proposed to solve the ''room problem'' of huge batholiths. Transformists (Read) supported it; magmatists (Bowen) opposed it.',null,true,3,1,1270) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f066','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','H. H. Read''s ''granite series'' runs from autochthonous granite (formed in place) through parautochthonous to intrusive (allochthonous) granite; his phrase was ''there are granites and granites''.','He meant that granites can form in more than one way. Deep in-place granites grade upward into moved magma bodies.',null,true,2,2,1271) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f067','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','The ''basic front'' (Doris Reynolds) is a zone enriched in iron, magnesium and calcium, thought to be pushed ahead of an advancing granitization front.','If a rock is turned into granite, the unwanted mafic elements must go somewhere. They were said to pile up just outside.',null,true,1,3,1272) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f068','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Migmatite is a ''mixed rock'' made of a dark metamorphic part and a light granitic part; the term was coined by J. J. Sederholm (1907) in Finland.','Migma = mixture in Greek. Migmatites form at the top end of metamorphism where rocks begin to melt.',null,true,3,1,1273) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f069','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','In a migmatite, the leucosome is the light quartz-feldspar part and the melanosome is the dark mafic part rich in biotite or hornblende.','Leuco = white, melano = black. Leucosome is the melt; melanosome is the residue left after melt was taken out.',null,true,3,1,1274) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f070','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','In a migmatite, the palaeosome is the older, unaltered parent rock and the neosome is the newly formed part (leucosome + melanosome).','Palaeo = old, neo = new. The terms are from Mehnert''s classification.',null,true,3,1,1275) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f071','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Migmatite structures include agmatite (breccia-like, angular blocks of palaeosome in neosome), stromatic (layered), ptygmatic (tightly folded veins) and nebulitic (ghost-like, nearly homogeneous).','Agma = fragment. Nebula = cloud; in nebulite the old rock is almost fully melted away.',null,true,3,1,1276) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f072','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Metatexite is a migmatite formed by low-degree partial melting that keeps its older structures; diatexite is formed by extensive melting that destroys them.','Meta-texis = partial melting, dia-texis = melting right through.',null,true,1,3,1277) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f073','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Lit-par-lit injection is the intrusion of thin granitic sheets bed by bed along foliation; arterite has injected leucosome, venite has leucosome segregated from the rock itself.','Lit-par-lit = ''bed by bed'' in French. Arterite, like arteries, is fed from outside; venite is home-grown.',null,true,2,2,1278) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f074','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Anatexis is the partial melting of crustal rocks during high-grade metamorphism; palingenesis is the making of new magma by complete remelting of older rocks.','The first melt has granite composition (quartz + alkali feldspar). With water present it starts at roughly 650-700 °C.',null,true,3,1,1279) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f075','geological-assistant','geological-assistant-m4','Plate tectonics and metamorphic zones','Blueschist-facies rocks form in subduction zones, where a cold slab is carried down quickly so that pressure rises much faster than temperature.','The geothermal gradient there is very low, about 10 °C per km or less. So blueschist is a marker of old subduction zones.','Kerala PSC paper 042/2025 (descriptive)',true,3,1,1280) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f076','geological-assistant','geological-assistant-m4','Plate tectonics and metamorphic zones','The facies series of a subducting oceanic slab is zeolite, prehnite-pumpellyite, blueschist, eclogite.','This is the high-pressure, low-temperature path. Dense eclogite adds to slab pull (the sinking force on the plate).','IIT-JAM Geology 2020; Kerala PSC paper 042/2025 (descriptive)',true,3,1,1281) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f077','geological-assistant','geological-assistant-m4','Plate tectonics and metamorphic zones','Continental collision belts show medium-pressure Barrovian metamorphism, magmatic arcs show low-pressure high-temperature metamorphism, and mid-ocean ridges show low-pressure hydrothermal ocean-floor metamorphism.','Each plate setting has its own geothermal gradient. So the facies series points to the tectonic setting.',null,true,3,1,1282) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f078','geological-assistant','geological-assistant-m4','Plate tectonics and metamorphic zones','Ultra-high-pressure (UHP) metamorphism is shown by coesite or diamond in crustal rocks; in India, coesite-bearing eclogite occurs in the Tso Morari complex, Ladakh.','Coesite needs depths of about 90 km or more. It proves Indian continental crust was subducted and then came back up.',null,true,2,2,1283) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f079','geological-assistant','geological-assistant-m4','Paired metamorphic belts','Paired metamorphic belts, a concept of A. Miyashiro (1961), are two parallel belts of similar age: a high-pressure low-temperature belt and a low-pressure high-temperature belt.','They form together at a subduction zone. One belt is the subduction complex, the other is the hot magmatic arc.','UPSC Geologist Exam 2018 Geology Paper II (descriptive); UPSC Geologist Mains 2020 Geology Paper II (descriptive)',true,3,1,1284) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f080','geological-assistant','geological-assistant-m4','Paired metamorphic belts','In a paired belt the high-pressure (blueschist) belt lies on the ocean or trench side and the low-pressure high-temperature belt with granites lies on the arc or continent side.','So the pair shows which way the old plate subducted: it dipped from the blueschist belt towards the hot belt.',null,true,3,1,1285) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f081','geological-assistant','geological-assistant-m4','Paired metamorphic belts','The classic paired belts of south-west Japan are the Sanbagawa belt (high pressure) and the Ryoke belt (low pressure, high temperature), separated by the Median Tectonic Line.','Sanbagawa has glaucophane schists; Ryoke has andalusite-sillimanite rocks and granites. Another pair is Franciscan and Sierra Nevada in California.',null,true,3,1,1286) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f082','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Fault rocks are grouped as incohesive (fault breccia, gouge), cohesive brittle cataclasite, and cohesive foliated mylonite formed by ductile flow; ultramylonite has over 90% fine matrix.','Shallow faults crush rock (brittle). Deeper, hotter shear zones make rock flow (ductile) and give mylonite.','IIT-JAM Geology 2019; Kerala PSC HSST Geology 2026 (paper 80/2026)',true,2,2,1287) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f083','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Pseudotachylite is a dark glassy vein rock formed by frictional melting during very fast fault slip (earthquakes) or meteorite impact.','It looks like tachylite (basalt glass) but is not volcanic. Hence ''pseudo''.',null,true,2,2,1288) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f084','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Charnockite was named by T. H. Holland after Job Charnock, whose tombstone in St. John''s Church, Kolkata, is made of this rock from St. Thomas Mount near Chennai.','Job Charnock is regarded as the founder of Calcutta. The type area is St. Thomas Mount - Pallavaram, Tamil Nadu.',null,true,3,1,1289) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f085','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Charnockite is a hypersthene (orthopyroxene)-bearing granite or quartz-feldspar gneiss of the granulite facies, with greasy bluish-grey quartz and feldspar.','Orthopyroxene shows very high temperature and dry conditions. The orthopyroxene tonalite of the charnockite series is called enderbite.',null,true,3,1,1290) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f086','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Khondalite is a quartz-garnet-sillimanite-graphite gneiss or schist, a granulite-facies metamorphosed pelitic sediment, named by T. L. Walker after the Khond people of Odisha.','Sillimanite and graphite show the parent was an alumina-rich, carbon-bearing clay. It is common in the Eastern Ghats and south Kerala.','IIT-JAM Geology 2019',true,3,1,1291) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f087','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Leptynite is a light-coloured, garnet-bearing quartz-feldspar granulite or gneiss, poor in mafic minerals, found with khondalite and charnockite in the Eastern Ghats and Kerala.','Think of it as a pale garnet-quartz-feldspar rock. It lacks the sillimanite and graphite of khondalite.',null,true,2,2,1292) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f088','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Incipient charnockite is patchy, arrested conversion of gneiss to charnockite along fractures and foliation; it is seen at Ponmudi in Kerala and Kabbaldurga in Karnataka.','CO2-rich fluids are thought to have lowered water activity, so biotite or hornblende broke down to orthopyroxene. ''Incipient'' means just beginning.',null,true,3,1,1293) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f089','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','The Kerala Khondalite Belt (Trivandrum Block) lies south of the Achankovil Shear Zone and consists of khondalite, leptynite, garnet-biotite gneiss and charnockite.','It is the main granulite-facies metasedimentary belt of south Kerala. Graphite and incipient charnockite occur in it.','Kerala PSC HSST Geology 2026 (paper 80/2026)',true,3,1,1294) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f090','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','The two great granulite terrains of India are the Southern Granulite Terrain (Tamil Nadu, Kerala, south Karnataka) and the Eastern Ghats Mobile Belt (Odisha, Andhra Pradesh).','Both expose deep crust with charnockite and khondalite. Most of Kerala''s basement belongs to the Southern Granulite Terrain.',null,true,3,1,1295) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f091','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Gondite is a metamorphosed manganese-rich sediment made of spessartine garnet and quartz, named by L. L. Fermor after the Gonds; it occurs in the Sausar Group of Madhya Pradesh and Maharashtra.','Spessartine is the manganese garnet. Gondite belts host the manganese ores of Balaghat, Nagpur and Bhandara.',null,true,3,1,1296) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f092','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Kodurite is a rock of K-feldspar, manganese garnet (spessartine-andradite) and apatite, named by Fermor from Kodur in the Eastern Ghats of Andhra Pradesh.','It occurs with khondalite and hosts manganese ore. Remember: gondite = Central India, kodurite = Andhra Pradesh.',null,true,3,1,1297) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f093','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Prograde metamorphism is the series of changes that take place as temperature (and usually pressure) rises; it drives off water and CO2, so higher-grade rocks hold fewer hydrous minerals.','Pro = forward. Clay and chlorite hold much water; garnet, sillimanite and pyroxene hold none. Retrograde metamorphism is the return journey.',null,true,3,1,1298) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f094','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','H. G. F. Winkler replaced facies names with four temperature-based grades: very low, low, medium and high grade, each bounded by specific mineral reactions.','He felt facies boundaries were fuzzy. In his scheme, high grade starts where muscovite breaks down in the presence of quartz.',null,true,2,2,1299) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f095','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Prehnite-pumpellyite facies rocks carry prehnite + pumpellyite + chlorite + albite; this facies and the zeolite facies (together ''sub-greenschist'', below about 300 °C) were set up by D. S. Coombs in New Zealand.','They fill the gap between diagenesis (changes in buried sediment) and greenschist facies. Coombs worked on buried volcanic sandstones of South Island.',null,true,2,2,1300) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f096','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Blueschist facies conditions are roughly 200-500 °C at pressures above about 0.6 GPa, equal to depths of more than about 20 km.','This is very cold for such depth. Textbooks differ a little on the limits, so learn the pattern: cold and deep.',null,false,2,2,1301) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f097','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Eclogite facies needs pressures above about 1.2 GPa (deeper than about 40 km) over a wide range of temperature; eclogite also comes up as xenoliths (carried fragments) in kimberlite pipes.','It is the deepest facies. Kimberlite xenoliths prove that eclogite exists in the upper mantle.',null,false,2,2,1302) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f098','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','Quartz changes to coesite at about 2.7 GPa (about 90 km depth); in the facies scheme coesite is stable in the eclogite facies.','Coesite in crustal rocks was first found in 1984, at Dora Maira (Western Alps) and in Norway. Diamond-bearing crustal rocks occur at Kokchetav, Kazakhstan.','Kerala PSC HSST Geology 2026 (paper 80/2026)',true,3,1,1303) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f099','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','The first reaction in metamorphosed siliceous dolomite is dolomite + quartz + water = talc + calcite + CO2; tremolite then forms from talc + calcite + quartz.','Dolomite gives the magnesium and quartz gives the silica. Calcite is left over at each step, so the rock stays a marble.',null,true,2,2,1304) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f100','geological-assistant','geological-assistant-m4','Regional and contact metamorphism of pelitic and impure calcareous rocks','Reactions in impure carbonate rocks release H2O and CO2, so their temperatures depend on fluid composition; they are plotted on T-XCO2 diagrams (XCO2 = share of CO2 in the fluid).','A water-rich fluid lets a decarbonation reaction run at lower temperature. So wollastonite can form early where water flushes through an aureole.',null,true,2,2,1305) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f101','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Maculose structure is the spotted or knotted look of contact-metamorphosed clay rocks (spotted slate), caused by scattered clots or porphyroblasts of cordierite, andalusite, biotite or carbon.','Macula = spot in Latin. Spots mark the outer aureole; nearer the contact the rock becomes hornfels.',null,true,3,1,1306) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f102','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Tyrrell''s five structures of metamorphic rocks are cataclastic, maculose, schistose (including slaty), granulose and gneissose.','Granulose means equal-sized grains with no foliation, as in quartzite and marble. It is the same idea as granoblastic texture.',null,true,2,2,1307) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f103','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Riecke''s principle: under directed stress a mineral dissolves at points of greatest stress and regrows where stress is least, so grains flatten at right angles to the squeezing.','This ''pressure solution'' helps to make foliation. It needs a thin film of pore fluid to carry the dissolved material.',null,true,2,2,1308) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f104','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','A corona is a reaction rim of new minerals around an older grain, and a symplectite is a fine worm-like intergrowth of two minerals; kelyphite is a symplectite rim around garnet.','They are frozen, unfinished reactions. In granulites they often show that pressure fell while the rock was still hot (decompression).',null,true,2,2,1309) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f105','geological-assistant','geological-assistant-m4','Textures and structures of metamorphic rocks','Crenulation cleavage forms when an older foliation is bent into tiny folds (crenulations) and a new cleavage develops along their limbs; it proves a second phase of deformation.','First foliation = S1, the new one = S2. It is common in phyllites and schists.','IIT-JAM Geology 2020',true,2,2,1310) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f106','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','Lithostatic (confining) pressure rises by about 0.027-0.03 GPa per km in the crust, so 1 GPa (10 kbar) corresponds to roughly 35 km depth.','Pressure = density x gravity x depth. With a rock density of 2800 kg/m3, each km adds about 27.5 MPa.','IIT-JAM Geology 2019',true,2,2,1311) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f107','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','The slope of a reaction curve on a P-T diagram is given by the Clausius-Clapeyron equation, dP/dT = ΔS/ΔV (entropy change divided by volume change).','Dehydration reactions have steep curves, so they mark temperature well. Solid-solid reactions with gentle slopes mark pressure well.','UPSC Geologist Mains 2020 Geology Paper II (descriptive)',true,2,2,1312) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f108','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','A petrogenetic grid, an idea of N. L. Bowen (1940), is a P-T diagram of intersecting reaction curves that divides P-T space into fields, each with its own stable mineral assemblages.','Find the field that matches the minerals in your rock and you have its P-T conditions. The Al2SiO5 diagram is the simplest grid.',null,true,2,2,1313) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f109','geological-assistant','geological-assistant-m4','Mineral assemblages and P/T conditions','At high pressure albite breaks down to jadeite + quartz; this reaction is a pressure marker of the blueschist and eclogite facies.','Jadeite is a dense sodium pyroxene. Pressure favours dense minerals, so light albite cannot survive deep in a subduction zone.',null,true,2,2,1314) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f110','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Barrow''s chlorite and biotite zones belong to the greenschist facies, while the staurolite, kyanite and sillimanite zones belong to the amphibolite facies; the garnet zone lies at the transition.','A zone uses one index mineral in pelites. A facies uses the whole assemblage, so several zones fit inside one facies.',null,true,3,1,1315) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f111','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Epidote-amphibolite facies metabasites carry hornblende + albite + epidote (with or without garnet); the facies is transitional between greenschist and amphibolite facies.','The amphibole has already become hornblende, but the plagioclase is still albite with epidote. Hence the mixed name.',null,true,2,2,1316) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f112','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','In granulite-facies pelites muscovite is absent and the typical assemblage is garnet + sillimanite + K-feldspar + quartz, with or without cordierite; khondalite is an example.','Muscovite has already broken down to K-feldspar + sillimanite. Biotite too is breaking down, to garnet or cordierite.',null,true,2,2,1317) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f113','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Ultra-high-temperature (UHT) metamorphism is granulite-facies metamorphism above 900 °C; sapphirine + quartz is its best-known diagnostic assemblage.','It is reported from the Eastern Ghats and the Madurai Block of South India. Spinel + quartz and orthopyroxene + sillimanite + quartz also point to UHT.',null,true,2,2,1318) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f114','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Holland (1900) described the ''charnockite series'' as hypersthene-bearing rocks ranging from acid (charnockite proper) through intermediate to basic (norite) and ultrabasic (pyroxenite), and regarded them as igneous.','Later work showed that many are metamorphic granulites. Today both igneous and metamorphic charnockites are accepted.',null,true,3,1,1319) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f115','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','The East Coast bauxite deposits of Odisha and Andhra Pradesh were formed by lateritic weathering of khondalite.','Khondalite is rich in alumina (sillimanite, garnet, feldspar). Tropical weathering washed away the silica and left aluminium behind.',null,true,2,2,1320) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f116','geological-assistant','geological-assistant-m4','Characteristics of different grades and facies of metamorphism','Granulite-facies metamorphism of the Kerala Khondalite Belt is of Pan-African age, about 550 million years (late Neoproterozoic to Cambrian).','The same event is seen in Sri Lanka and Madagascar, which lay next to Kerala in Gondwana.',null,true,2,2,1321) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f117','geological-assistant','geological-assistant-m4','Plate tectonics and metamorphic zones','Rocks of continental collision belts usually follow a clockwise P-T-t path: pressure peaks first during crustal thickening, temperature peaks later, then both fall during uplift and erosion.','Rock conducts heat slowly, so heating lags behind burial. ''Clockwise'' assumes pressure is plotted upward on the P-T diagram.',null,true,2,2,1322) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f118','geological-assistant','geological-assistant-m4','Plate tectonics and metamorphic zones','Approximate geothermal gradients: high-pressure series about 10 °C/km or less, medium-pressure (Barrovian) series about 20-30 °C/km, low-pressure (Buchan or Abukuma) series above about 40 °C/km.','Gradient = temperature rise per km of depth. Cold slab = low gradient; hot arc with rising magma = high gradient. Exact numbers differ between textbooks.',null,false,2,2,1323) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f119','geological-assistant','geological-assistant-m4','Plate tectonics and metamorphic zones','In India, blueschists occur in the Indus Suture Zone of Ladakh (Sapi-Shergol area) and in the Nagaland-Manipur ophiolite belt; both mark subduction of Tethyan ocean floor.','A suture is the scar where an ocean closed. Blueschist with ophiolite (slices of ocean floor) is its typical mark.',null,true,2,2,1324) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f120','geological-assistant','geological-assistant-m4','Paired metamorphic belts','Miyashiro recognised three paired belts in Japan: Sangun-Hida, Sanbagawa-Ryoke and Kamuikotan-Hidaka (high-pressure belt named first); Wakatipu-Tasman in New Zealand is another pair.','Each pair records a separate period of subduction under the island arc. Sanbagawa-Ryoke is the one exams ask most.',null,true,2,2,1325) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f121','geological-assistant','geological-assistant-m4','Paired metamorphic belts','Paired belts mark old subduction zones, but the two belts need not have formed side by side; some were brought together later by large strike-slip faults such as Japan''s Median Tectonic Line.','This is the modern view. The original spacing between trench-side and arc-side belts would have been 100 km or more.',null,true,1,3,1326) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f122','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Tuttle and Bowen (1958) showed that most granites plot near the minimum-melting composition of the quartz-albite-orthoclase-water system, strong evidence that granites crystallised from melts.','A rock made by metasomatism need not have this special composition. The result swung the granite debate towards the magmatists.',null,true,2,2,1327) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f123','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Field evidence cited for granitization includes gradational contacts, ''ghost stratigraphy'' (relict bedding traceable through the granite) and large K-feldspar crystals grown in country rock and xenoliths.','An intruding magma should cut and push aside the old layers. Layers passing undisturbed through granite suggested change in place. Today most such granites are explained by melting in place (anatexis).',null,true,2,2,1328) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f124','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Lindgren''s law of equal volumes: metasomatic replacement takes place volume for volume, so the shape and texture of the replaced rock, mineral or fossil can be preserved.','The old mineral dissolves and the new one is deposited at the same moment. Pseudomorphs (false forms) and petrified wood show this.',null,true,2,2,1329) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4b-f125','geological-assistant','geological-assistant-m4','Metasomatism and granitization, migmatites','Exoskarn replaces the carbonate country rock outside the intrusion; endoskarn replaces the margin of the intrusion itself.','Exo = outside, endo = inside. Most skarn ore lies in the exoskarn.',null,true,2,2,1330) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f001','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Provenance means the source area of a sediment: its parent rocks, relief and climate, worked out from the composition of the sediment.','Grains carry a record of where they came from. Feldspar, rock fragments and heavy minerals point back to the parent rock.','UPSC Geologist Mains 2019 Geology Paper II',true,2,2,1331) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f002','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Heavy minerals are accessory detrital grains with specific gravity above about 2.9; they are separated from quartz and feldspar by letting them sink in bromoform (specific gravity 2.89).','Quartz (2.65) and feldspar float in bromoform, while zircon, garnet, rutile and others sink. The sunk fraction is studied for provenance.',null,true,2,2,1332) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f003','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','The ZTR index is the percentage of zircon + tourmaline + rutile among the transparent (non-opaque) heavy minerals; a high ZTR index means a mineralogically mature sediment.','These three are ultra-stable and survive long transport and recycling. Less stable heavy minerals get destroyed, so ZTR rises with maturity.',null,true,3,1,1333) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f004','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Kyanite, sillimanite, staurolite and garnet as heavy minerals point to a high-grade metamorphic source; augite, hypersthene and chromite point to a basic or ultrabasic igneous source.','Each parent rock has its own typical accessory minerals. The heavy mineral suite works like a fingerprint of the source rock.',null,true,2,2,1334) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f005','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Abundant fresh feldspar in a sandstone (arkose) points to a granite or gneiss source with fast erosion and quick burial, usually under high relief or a dry or cold climate.','Feldspar weathers easily to clay. It survives only when chemical weathering is weak or erosion is too fast for it to act.',null,true,2,2,1335) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f006','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Diagenesis covers all physical, chemical and biological changes in a sediment after deposition and before metamorphism, at low temperature and pressure.','It is the stage between loose sediment and metamorphic rock. Compaction, cementation, dissolution and replacement all belong here.','UPSC Assistant Hydrogeologist (CGWB) 2019',true,3,1,1336) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f007','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Compaction squeezes out pore water and reduces porosity, far more in mud than in sand; compaction plus cementation turns loose sediment into rock (lithification).','Clay flakes start with very open, watery packing and collapse under load. Sand grains already touch each other, so they compact little.',null,true,3,1,1337) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f008','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Common sandstone cements are silica (quartz overgrowths), calcite and iron oxide; a quartz overgrowth grows in optical continuity with its host grain.','New silica continues the crystal lattice of the old grain, so both go dark together under crossed polars. A thin dust line often marks the old grain edge.',null,true,2,2,1338) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f009','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Authigenic minerals grow in place inside the sediment after deposition; examples are glauconite, pyrite, quartz and feldspar overgrowths and many clay minerals.','Authigenic means ''born on the spot''. The opposite is detrital (allogenic), meaning carried in from outside.',null,true,2,2,1339) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f010','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Dolomitisation replaces calcite or aragonite by dolomite, CaMg(CO3)2; mole-for-mole replacement shrinks the solid volume by about 12-13% and can create porosity.','Dolomite is denser than calcite, so the same number of moles takes less space. This is why many dolomites are good oil reservoirs.','Goa PSC Assistant Professor Geology 2021',true,3,1,1340) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f092','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Sanidine, glass shards and clear embayed quartz in a sandstone point to an acid volcanic source; polycrystalline quartz with strong undulose (wavy) extinction points to a metamorphic source.','Sanidine is the high-temperature potash feldspar of rhyolites. Strained, many-crystal quartz is made by deformation during metamorphism.','Goa PSC Assistant Professor Geology 2021',true,2,2,1341) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f093','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','Dickinson''s QFL triangle (quartz, feldspar, lithic fragments) links sandstone composition to plate-tectonic setting through three provenance types: continental block, magmatic arc and recycled orogen.','Cratons supply quartz and feldspar, volcanic arcs supply feldspar and volcanic fragments, and uplifted fold belts supply recycled quartz and sedimentary fragments.',null,true,2,2,1342) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f094','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','With deeper burial, sand grain contacts change from point (tangential) to long, then concavo-convex, then sutured, as compaction and pressure solution increase.','Load from above first pushes grains closer, then dissolves them where they touch. Sutured means interlocking like a jigsaw.',null,true,2,2,1343) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f095','geological-assistant','geological-assistant-m4','Provenance and diagenesis of sediments','In carbonate diagenesis the vadose zone lies above the water table, with air and water in the pores, and gives meniscus and pendant (hanging-drop) cements; the water-filled phreatic zone below gives even rim cements.','Above the water table, water only clings at grain contacts or hangs under grains, so cement grows only there. Below it, cement can grow all around the grain.','Goa PSC Assistant Professor Geology 2021',true,2,2,1344) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f011','geological-assistant','geological-assistant-m4','Sedimentary textures','Roundness measures how sharp a grain''s corners and edges are; it increases with abrasion during transport. Wadell defined it as average corner radius divided by the radius of the largest inscribed circle.','Corners get knocked off as grains travel. So roundness tells about transport and reworking, not about the overall shape.',null,true,3,1,1345) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f012','geological-assistant','geological-assistant-m4','Sedimentary textures','Sphericity measures how closely a grain''s overall form approaches a sphere; it depends mainly on the original crystal shape and is independent of roundness.','A cube with smoothed corners is well rounded but still not a sphere. A long zircon stays long however far it travels.',null,true,3,1,1346) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f013','geological-assistant','geological-assistant-m4','Sedimentary textures','Folk''s textural maturity stages: immature (over 5% clay), submature (under 5% clay but poorly sorted), mature (well sorted, grains not rounded), supermature (well sorted and rounded).','Energy first removes clay, then sorts the sand, and last of all rounds the grains. Each step needs more reworking than the one before.',null,true,3,1,1347) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f014','geological-assistant','geological-assistant-m4','Sedimentary textures','Mineralogical (compositional) maturity is judged by the ratio of stable grains (quartz, chert) to unstable grains (feldspar, rock fragments); quartz arenite is the most mature sandstone.','Weathering and long transport destroy weak minerals. What is left in the end is almost pure quartz.',null,true,3,1,1348) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f091','geological-assistant','geological-assistant-m4','Sedimentary textures','Textural and mineralogical maturity can differ: a wind-blown sand may be well sorted and well rounded (texturally mature) yet still rich in feldspar (mineralogically immature).','Wind sorts and rounds grains mechanically, but in a dry climate there is little chemical weathering to destroy feldspar.','Kerala PSC HSST Geology 2026 (QP 80/2026/OL)',true,2,2,1349) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f015','geological-assistant','geological-assistant-m4','Framework, matrix and cement of terrigenous sediments','A terrigenous rock has three parts: framework grains (sand or gravel that carry the load), matrix (fine detrital clay and silt, under about 30 micrometres in sandstone) and cement (minerals precipitated later in pores).','Matrix arrives with the grains during deposition. Cement is chemical and comes afterwards, during diagenesis.',null,true,2,2,1350) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f016','geological-assistant','geological-assistant-m4','Framework, matrix and cement of terrigenous sediments','Conglomerate has rounded clasts larger than 2 mm; breccia has angular clasts of the same size, showing very little transport.','Rounding needs transport. Angular pieces mean the fragments were deposited close to where they broke off (scree, fault zone, collapse).',null,true,2,2,1351) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f017','geological-assistant','geological-assistant-m4','Framework, matrix and cement of terrigenous sediments','Orthoconglomerate is grain-supported with less than 15% matrix; paraconglomerate is matrix-supported with more than 15% matrix, such as tillite and pebbly mudstone.','Running water washes fines away and leaves clasts touching. Glaciers and debris flows dump clasts and mud together.',null,true,3,1,1352) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f018','geological-assistant','geological-assistant-m4','Framework, matrix and cement of terrigenous sediments','Shale is a fissile mudrock: it splits into thin sheets because its platy clay minerals lie parallel. Mudstone is non-fissile. Mudrocks are the most abundant sedimentary rocks.','Compaction rotates clay flakes flat, giving planes of easy splitting. Roughly half of all sedimentary rock is mudrock.',null,true,2,2,1353) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f019','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Udden-Wentworth size limits: boulder over 256 mm, cobble 64-256 mm, pebble 4-64 mm, granule 2-4 mm, sand 1/16-2 mm, silt 1/256-1/16 mm, clay under 1/256 mm.','It is a geometric scale: each main boundary is a power of 2. Memory hook: 256, 64, 4, 2, 1/16, 1/256.','Kerala PSC HSST Geology 2026 (QP 80/2026/OL)',true,3,1,1354) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f020','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Krumbein''s phi scale: phi = -log2(diameter in mm). So 2 mm = -1 phi, 1 mm = 0 phi, 1/16 mm = 4 phi and 1/256 mm = 8 phi; a bigger phi means a finer grain.','The minus sign makes the common sand and mud sizes positive numbers. Phi turns the Wentworth boundaries into whole numbers that are easy to plot.',null,true,3,1,1355) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f021','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Sieving is used to measure sand and gravel sizes; pipette and hydrometer methods are used for silt and clay and work on settling speed (Stokes'' law).','Silt and clay are too fine for sieves. Finer grains settle more slowly, so settling time gives the size.',null,true,3,1,1356) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f022','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Stokes'' law: the settling velocity of a small sphere is proportional to the square of its diameter and to the density difference between grain and fluid; it holds only for silt- and clay-size particles.','Double the diameter and the grain settles four times faster. Larger grains create turbulence, so the law fails for sand and gravel.',null,true,2,2,1357) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f023','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Folk and Ward graphic mean: Mz = (phi16 + phi50 + phi84) / 3. The median is simply phi50 read from the cumulative curve.','Three percentiles sample the coarse third, middle and fine third of the curve. This gives a better average than the median alone.',null,true,2,2,1358) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f024','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Folk and Ward sorting (inclusive graphic standard deviation) = (phi84 - phi16)/4 + (phi95 - phi5)/6.6. Under 0.35 phi is very well sorted; over 1.0 phi is poorly sorted.','Sorting is the spread of sizes. A small spread means the current or waves selected one size, as on beaches and dunes.',null,true,3,1,1359) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f025','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Skewness measures the asymmetry of the size curve: positive (fine-skewed) means a tail of excess fine grains; negative (coarse-skewed) means a tail of excess coarse grains.','On the phi scale fine sizes have larger positive numbers. So a tail towards the fine side is a tail towards positive phi.',null,true,3,1,1360) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f026','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Beach sands tend to be negatively skewed, while river and dune sands tend to be positively skewed.','Waves wash the fines out of beach sand, leaving a coarse tail. Rivers and wind keep some fine material in suspension load, giving a fine tail.',null,true,2,2,1361) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f027','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Kurtosis measures the peakedness of the size curve: a normal curve has KG = 1.0 (mesokurtic); leptokurtic curves are sharply peaked and platykurtic curves are flat.','Hook: ''lepto'' means slender (tall peak), ''platy'' means flat like a plate. It compares sorting in the centre with sorting in the tails.',null,true,3,1,1362) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f096','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Sand classes on the phi scale: very coarse -1 to 0 (2-1 mm), coarse 0 to 1 (1-0.5 mm), medium 1 to 2 (0.5-0.25 mm), fine 2 to 3 (0.25-0.125 mm), very fine 3 to 4 (0.125-0.0625 mm).','Each class is half the size of the one before, so each step is exactly one phi unit. Sand spans five phi units, from -1 to 4.',null,true,3,1,1363) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f097','geological-assistant','geological-assistant-m4','Definition, measurement and interpretation of grain size','Visher''s log-probability plot splits a sand''s cumulative size curve into straight segments for three transport populations: traction (rolling), saltation (jumping) and suspension.','Each way of moving grains produces its own roughly normal size population, and a normal population plots as a straight line on probability paper.',null,true,2,2,1364) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f028','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','A bed is a sedimentary layer thicker than 1 cm; a lamina is a layer thinner than 1 cm.','The 1 cm limit is only a convention, but it is the one used in all standard textbooks.','UPSC Geologist Mains 2019 Geology Paper II',true,2,2,1365) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f029','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Cross-bedding has inclined foreset layers that dip downcurrent; planar (tabular) sets form from straight-crested bedforms and trough sets from curved-crested dunes.','Sand avalanches down the lee (sheltered) face of a moving ripple or dune. Each avalanche layer is one foreset, so foresets point the way the current went.',null,true,3,1,1366) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f030','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','In cross-bedding the foresets curve gently (tangentially) into the lower surface and are sharply truncated at the top, so the truncated side marks the top of the bed.','The next current erodes the upper part of the set. If the cut-off side is found at the bottom, the bed is overturned.',null,true,2,2,1367) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f031','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Herringbone cross-bedding has foresets dipping in opposite directions in adjacent sets; it records reversing flood and ebb tidal currents.','The tide flows in and then out, so dunes migrate both ways. The pattern looks like the bones of a fish.',null,true,3,1,1368) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f032','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Hummocky cross-stratification (HCS) is formed by storm waves on the shelf, between fair-weather wave base and storm wave base.','Only big storm waves reach that depth. After the storm nothing reworks the bed, so the low mounds (hummocks) are preserved.',null,true,2,2,1369) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f033','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','In graded bedding the grain size decreases upward within one bed; it forms from a waning current, typically a turbidity current, and the coarse part marks the bottom.','As the flow slows down, the heaviest grains drop first and the finest last.',null,true,3,1,1370) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f034','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Symmetrical (wave) ripples have sharp crests and rounded troughs, and the crests point to the top; asymmetrical (current) ripples have their steep lee side facing downcurrent.','Waves move water to and fro, giving equal slopes. A one-way current pushes sand up the gentle side and drops it down the steep side.',null,true,3,1,1371) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f035','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Flaser bedding is rippled sand with thin mud streaks; lenticular bedding is mud with isolated sand lenses; wavy bedding lies between. All three are typical of tidal flats.','Sand moves when the tide runs and mud settles at slack water. The sand-to-mud ratio decides which of the three forms.',null,true,3,1,1372) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f036','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Sole marks are casts on the underside of sandstone beds lying on mud: flute casts (current scours with a bulbous upcurrent nose) and tool marks (groove, prod, bounce, skip casts).','The current scours or scratches the mud floor, and the next sand fills the hollows. Flute casts are the classic direction markers in turbidites.','Kerala PSC Assistant Geologist 2025 (QP 26/2025/OL)',true,3,1,1373) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f037','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Groove casts and parting lineation give only the line (trend) of flow; flute casts, cross-bedding, asymmetrical ripples and pebble imbrication give the actual direction (sense) of flow.','A straight scratch looks the same from both ends. A structure with different upcurrent and downcurrent ends shows which way the water went.','UPSC Assistant Hydrogeologist (CGWB) 2019',true,3,1,1374) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f038','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Mud cracks (desiccation cracks) form polygons when wet mud dries in air; the cracks are V-shaped and narrow downward, so they show the top and prove subaerial exposure.','Drying starts at the surface, so the crack is widest there. Found in tidal flats, floodplains and dried lake beds.',null,true,3,1,1375) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f039','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Bouma sequence of a turbidite, base to top: Ta massive graded sand, Tb parallel-laminated sand, Tc ripple cross-laminated or convolute sand, Td laminated silt, Te pelagic mud.','It records one turbidity current slowing down: fast dumping first, then traction, then quiet settling. Complete sequences are rare.',null,true,3,1,1376) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f040','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Top-and-bottom (way-up) criteria include graded bedding, truncated cross-beds, wave-ripple crests, mud cracks, sole marks, load casts and partly filled (geopetal) cavities.','Each of these looks different upside down. They let a geologist tell whether folded beds are the right way up or overturned.',null,true,2,2,1377) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f041','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','A rose diagram is a circular histogram of palaeocurrent readings: unimodal for rivers and deltas, bimodal-bipolar (two peaks 180 degrees apart) for tidal settings.','Rivers flow one way down the slope. Tides flow in and out, giving two opposite peaks. Tilted beds must first be rotated back to horizontal.','UPSC Geologist Mains 2019 Geology Paper II',true,3,1,1378) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f087','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Load casts are rounded bulges of sand that sank into the soft mud below because sand is denser; the mud squeezed up between them forms flame structures. They show the bottom of a bed but no current direction.','Heavy wet sand on weak mud is unstable, so it sags. No current is involved, so there is no flow direction to read.',null,true,3,1,1379) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f088','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Soft-sediment deformation structures (convolute lamination, slump folds, load casts, dish-and-pillar structures) form before lithification in water-saturated sediment and are favoured by rapid sedimentation.','Fast deposition traps water in loose sediment. The sediment stays weak and deforms easily when loaded or shaken.','Goa PSC Assistant Professor Geology 2021',true,2,2,1380) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f089','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','In river gravels, flat pebbles stack like roof tiles (imbrication) with their flat faces dipping upstream; this gives the flow direction.','A pebble leaning upstream is the most stable position against the current. Memory hook: pebbles bow down toward the source.',null,true,2,2,1381) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f090','geological-assistant','geological-assistant-m4','Primary structures, palaeocurrent analysis','Ripples and dunes belong to the lower flow regime; plane beds with parting lineation and antidunes belong to the upper flow regime. Antidunes need supercritical flow (Froude number above 1).','As flow gets faster the bed changes from ripples to dunes to a flat bed to antidunes. Supercritical means fast, shallow, shooting flow.',null,true,2,2,1382) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f042','geological-assistant','geological-assistant-m4','Biogenic and chemical sedimentary structures','Stromatolites are laminated structures built when mats of cyanobacteria (blue-green algae) trap and bind sediment; they are common in Precambrian carbonates such as the Vindhyan and Cuddapah.','They are the commonest sign of life in the Precambrian. They declined later when grazing animals appeared and ate the mats.',null,true,3,1,1383) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f043','geological-assistant','geological-assistant-m4','Biogenic and chemical sedimentary structures','Trace fossils (ichnofossils) are tracks, trails, burrows and borings that record animal behaviour; intense burrowing (bioturbation) mixes the sediment and destroys primary lamination.','A trace fossil is always found where it was made, so it is a reliable guide to the environment. It cannot be transported like a shell.',null,true,2,2,1384) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f044','geological-assistant','geological-assistant-m4','Biogenic and chemical sedimentary structures','Seilacher''s marine ichnofacies from shore to deep sea: Skolithos (sandy shore, vertical burrows), Cruziana (shelf), Zoophycos (slope), Nereites (deep-sea turbidites, grazing trails).','In rough shallow water animals hide in deep vertical tubes. In the quiet deep sea they graze the mud surface in neat horizontal patterns.',null,true,2,2,1385) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f045','geological-assistant','geological-assistant-m4','Biogenic and chemical sedimentary structures','A concretion grows by mineral precipitation around a nucleus, often in concentric layers; a nodule is an irregular lump without internal structure, such as chert (flint) nodules in limestone.','These are chemical (diagenetic) structures. They form inside the sediment after deposition, not by currents.','UPSC Geologist Mains 2019 Geology Paper II',true,2,2,1386) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f046','geological-assistant','geological-assistant-m4','Biogenic and chemical sedimentary structures','Stylolites are irregular, tooth-like (sutured) seams formed by pressure solution, most common in limestones and lined by insoluble residue such as clay and iron oxide.','Under load the rock dissolves along a surface. The insoluble dirt stays behind as a dark zigzag line.',null,true,3,1,1387) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f047','geological-assistant','geological-assistant-m4','Biogenic and chemical sedimentary structures','A geode is a hollow, roughly spherical cavity lined with crystals (quartz, calcite) pointing inward; a septarian nodule is a concretion with radiating cracks filled by calcite.','A geode grows inward from the wall into an empty space. A concretion grows outward from a centre and is solid.',null,true,1,3,1388) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f048','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Facies is the sum of the lithological and fossil characters of a sedimentary unit that reflect its environment of deposition; the term was introduced by Gressly in 1838.','Facies means ''face'' or appearance of the rock. Same age rocks can have different facies in different environments.',null,true,2,2,1389) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f049','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Walther''s law: facies found in a conformable vertical succession were once deposited side by side; the law does not hold across unconformities.','When the shoreline shifts, neighbouring environments migrate over each other. So the vertical pile repeats the sideways arrangement.',null,true,3,1,1390) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f050','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','A meandering river point bar gives a fining-upward sequence: channel lag gravel, cross-bedded sand, rippled fine sand, then floodplain mud; it builds by lateral accretion.','Flow is strongest on the channel floor and weakest on the bank top. As the bend migrates sideways, these zones stack one above another.',null,true,3,1,1391) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f051','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','A prograding (advancing) delta gives a coarsening-upward sequence: prodelta mud, then delta-front sand, then delta-plain channel sand, mud and coal.','As the delta builds seaward, the sandy river mouth moves over the earlier offshore mud. Coarse over fine is the delta signature.',null,true,3,1,1392) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f052','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Aeolian (wind-blown) dune sandstones show very large-scale, steep cross-bedding, excellent sorting and rounding, frosted quartz grains, and almost no clay or mica.','Wind carries only a narrow size range and blows clay and mica flakes away. Grain collisions in air are harsh, so grains get rounded and frosted.',null,true,3,1,1393) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f053','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Glacial till is unsorted and unstratified; lithified till is tillite, with faceted and striated clasts. The Talchir Boulder Bed at the base of the Gondwana sequence is the Indian example.','Ice carries boulders and clay together and drops them without sorting. Scratches (striae) on clasts come from grinding against bedrock.',null,true,3,1,1394) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f054','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','A varve is a pair of laminae laid down in one year in a glacial lake: a light, coarser summer layer and a dark, clay-rich winter layer.','Meltwater brings silt in summer. In winter the lake freezes and only fine clay settles. Counting varves gives years.',null,true,2,2,1395) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f055','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Turbidites are deposited by turbidity currents (dense, sediment-laden underflows), mostly on deep-sea submarine fans; the Bengal Fan is the largest submarine fan in the world.','The muddy water is heavier than clear sea water and rushes down the slope. The Ganga-Brahmaputra feeds the Bengal Fan.',null,true,3,1,1396) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f056','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Pelagic (open ocean) sediments: calcareous ooze above the carbonate compensation depth (CCD, about 4-5 km), siliceous ooze of radiolaria and diatoms, and red clay in the deepest basins.','Below the CCD cold, CO2-rich water dissolves calcium carbonate shells. Only clay and silica survive there.','UPSC Assistant Hydrogeologist (CGWB) 2019',true,2,2,1397) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f057','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','A sabkha is a supratidal salt flat on an arid coast; gypsum, anhydrite and halite grow inside its sediment by capillary evaporation of saline groundwater.','Heat draws salty groundwater up to the surface where it evaporates. Nodular anhydrite with ''chicken-wire'' texture is the typical product.','Kerala PSC Assistant Geologist 2025 (QP 26/2025/OL)',true,2,2,1398) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f058','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Evaporating seawater precipitates salts in order of increasing solubility: calcium carbonate first, then gypsum, then halite, and last the potassium-magnesium salts (sylvite, carnallite).','The least soluble salt comes out first. Hook: Carbonate - Gypsum - Halite - Potash.',null,true,3,1,1399) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f059','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Chert is a hard rock of microcrystalline quartz; bedded cherts come from siliceous oozes of radiolaria and diatoms, nodular cherts from replacement of limestone. Flint and jasper are varieties.','Silica shells dissolve and re-precipitate as tiny quartz crystals. Flint is the dark chert of chalk; jasper is red from iron oxide.',null,true,2,2,1400) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f060','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Banded iron formations (BIF) are thin alternating bands of iron oxide and chert, almost all Precambrian: Algoma type is small and volcanic-related, Superior type is large and shelf-deposited.','They formed when the early oceans held dissolved iron that was precipitated as oxygen appeared. Indian BIFs (BHQ, BHJ) host the main iron ores.','Kerala PSC Assistant Geologist 2025 (QP 26/2025/OL)',true,2,2,1401) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f061','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Phosphorite is a marine sedimentary rock rich in phosphate minerals (collophane, francolite), formed on shelves below upwelling water; Jhamarkotra near Udaipur has stromatolitic phosphorite in the Aravalli Supergroup.','Upwelling brings nutrient-rich deep water to the shelf, and phosphate gets fixed in the sediment. It is the main raw material for phosphate fertiliser.','Kerala PSC Assistant Geologist 2025 (QP 26/2025/OL)',true,2,2,1402) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f098','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Galloway''s delta triangle: river-dominated deltas are bird''s-foot shaped (Mississippi), wave-dominated deltas are smooth and arcuate (Nile, Sao Francisco), and tide-dominated deltas have funnel-shaped channels with tidal sand ridges (Ganga-Brahmaputra).','The shape of a delta shows which force wins: the river building out, waves smoothing the front, or tides stretching sand bars along the channels.',null,true,3,1,1403) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f099','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','An alluvial fan forms where a stream leaves a mountain front onto a plain; its deposits are poorly sorted conglomerates and debris-flow beds (fanglomerate) that become finer away from the apex.','The stream suddenly spreads out and slows down, so it drops its coarsest load first, right at the mountain front.','Goa PSC Assistant Professor Geology 2021',true,2,2,1404) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f100','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','A prograding beach-shoreface gives a coarsening-upward sequence: bioturbated offshore mud, hummocky cross-stratified lower shoreface sand, trough cross-bedded upper shoreface sand, and gently seaward-dipping laminated foreshore (beach) sand on top.','Wave energy increases toward the shore, so as the coast builds seaward, higher-energy sands are stacked over lower-energy muds.',null,true,2,2,1405) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f101','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','Dropstones are isolated pebbles or boulders that fell from floating ice into fine laminated mud, bending the laminae below; they are evidence of ice-rafting in glacial lakes or seas.','Quiet water cannot carry a boulder into mud. Only melting ice floating above can drop it there.',null,true,2,2,1406) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f102','geological-assistant','geological-assistant-m4','Sedimentary environment and facies','In Usiglio''s seawater evaporation experiment, gypsum begins to precipitate when the water is reduced to about 19% of its original volume, and halite when it is reduced to about 10%.','Less soluble salts come out first. About four-fifths of the water must go before gypsum forms, and about nine-tenths before common salt forms.',null,true,2,2,1407) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f062','geological-assistant','geological-assistant-m4','Classification of sandstones','In the Dott (Pettijohn) scheme, sandstones with less than 15% matrix are arenites, those with 15-75% matrix are wackes, and rocks with over 75% matrix are mudstones.','Matrix content is the first split. After that, the rock is named from its quartz, feldspar and rock fragment proportions.','Goa PSC Assistant Geologist 2021',true,3,1,1408) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f063','geological-assistant','geological-assistant-m4','Classification of sandstones','Quartz arenite has more than 95% quartz among its framework grains; it is well sorted and well rounded and forms on stable cratons, beaches and dunes after long reworking.','It is the end product of sandstone evolution. Everything weaker than quartz has been destroyed.',null,true,3,1,1409) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f064','geological-assistant','geological-assistant-m4','Classification of sandstones','Arkose is a sandstone with more than 25% feldspar; it is derived from granite or gneiss and is often pink or red.','The pink colour comes from potash feldspar and iron oxide. It forms close to uplifted granitic basement, often in rift basins.',null,true,3,1,1410) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f065','geological-assistant','geological-assistant-m4','Classification of sandstones','Greywacke is a dark, hard, poorly sorted sandstone with more than 15% matrix plus feldspar and rock fragments; it is typical of turbidites in orogenic belts.','Turbidity currents dump sand and mud together without sorting. Hook: greywacke = ''dirty sandstone''.',null,true,3,1,1411) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f066','geological-assistant','geological-assistant-m4','Classification of sandstones','Folk''s sandstone classification plots quartz, feldspar and rock fragments (QFR) after ignoring the matrix; its names include quartzarenite, subarkose, sublitharenite, arkose and litharenite.','Folk treats matrix as a texture (maturity) feature, not a composition feature. Dott''s scheme instead uses matrix to separate arenite from wacke.',null,true,2,2,1412) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f103','geological-assistant','geological-assistant-m4','Classification of sandstones','In Dott''s scheme the sandstone name follows the dominant non-quartz grain: more feldspar than rock fragments gives arkosic (feldspathic) arenite or wacke; more rock fragments than feldspar gives lithic arenite or wacke.','First check matrix (under or over 15%) to choose arenite or wacke. Then compare feldspar with rock fragments to choose the prefix.','Goa PSC Assistant Geologist 2021',true,3,1,1413) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f067','geological-assistant','geological-assistant-m4','Classification of limestone','Folk''s limestone scheme uses allochems (intraclasts, ooids, fossils, pellets), micrite (lime mud) and sparite (clear calcite cement); names join a prefix intra-, oo-, bio- or pel- to -micrite or -sparite, as in oosparite.','Allochems are like sand grains, micrite like clay matrix and sparite like cement. So the idea copies sandstone description.',null,true,3,1,1414) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f068','geological-assistant','geological-assistant-m4','Classification of limestone','Micrite (calcite mud finer than 4 micrometres) indicates quiet water; sparite cement between grains indicates agitated water that washed the mud away.','Mud settles only where water is calm. Where waves winnow the mud, empty pores remain and are later filled by clear spar.',null,true,2,2,1415) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f069','geological-assistant','geological-assistant-m4','Classification of limestone','Dunham''s classification is based on depositional texture: mudstone, wackestone, packstone and grainstone (in order of increasing energy), plus boundstone and crystalline carbonate.','It asks two simple questions: is there lime mud, and do the grains touch each other? This makes it easy to use in the field and on cores.',null,true,3,1,1416) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f070','geological-assistant','geological-assistant-m4','Classification of limestone','Dunham: mudstone is mud-supported with under 10% grains; wackestone is mud-supported with over 10% grains; packstone is grain-supported with mud; grainstone is grain-supported without mud; boundstone is organically bound (reef).','Hook in order of less mud: Mud - Wacke - Pack - Grain. Boundstone equals Folk''s biolithite.','Goa PSC Assistant Geologist 2021; Goa PSC Assistant Professor Geology 2021',true,3,1,1417) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f071','geological-assistant','geological-assistant-m4','Classification of limestone','Ooids are spherical coated grains smaller than 2 mm with concentric layers around a nucleus; they form in warm, shallow, agitated sea water. Similar grains larger than 2 mm are pisoids.','Rolling by waves lets carbonate coat the grain evenly on all sides. A rock made of ooids is an oolite.',null,true,3,1,1418) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f104','geological-assistant','geological-assistant-m4','Classification of limestone','Embry and Klovan extended Dunham''s scheme: floatstone (matrix-supported) and rudstone (grain-supported) for limestones with over 10% grains larger than 2 mm, and bafflestone, bindstone and framestone for reef boundstones.','Dunham had no names for very coarse grains or for different reef-building styles. Rudstone is the coarse cousin of grainstone and packstone.',null,true,2,2,1419) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f105','geological-assistant','geological-assistant-m4','Classification of limestone','Folk''s limestone scheme also has biolithite (reef rock built in place by organisms, equal to Dunham''s boundstone) and dismicrite (micrite with patches of sparry calcite).','These two types do not fit the allochem-plus-micrite-or-sparite naming, so Folk gave them separate names.',null,true,2,2,1420) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f072','geological-assistant','geological-assistant-m4','Sedimentary basins of India','India has 26 sedimentary basins covering about 3.36 million sq km (onland plus offshore), as listed by the Directorate General of Hydrocarbons (DGH) after the 2017 resource reassessment.','DGH is the technical arm of the Petroleum Ministry. The figure was checked on the Ministry website in 2026.',null,true,2,2,1421) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f073','geological-assistant','geological-assistant-m4','Sedimentary basins of India','Since 2017 DGH uses three basin categories: Category I (commercial production, 7 basins), Category II (discoveries but no commercial production, 5 basins) and Category III (prospective only, 14 basins). The older scheme had four categories.','The category follows the maturity of resources: reserves, contingent resources, or only prospective resources. Older books still show Category I to IV.',null,true,2,2,1422) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f074','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The seven Category I (producing) basins are Cambay, Mumbai Offshore, Rajasthan, Krishna-Godavari, Cauvery, Assam Shelf and Assam-Arakan Fold Belt.','These are the only basins with established commercial oil and gas production in the DGH list (as seen in 2026).',null,true,3,1,1423) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f075','geological-assistant','geological-assistant-m4','Sedimentary basins of India','Category II basins (DGH three-tier scheme) are Kutch, Saurashtra, Vindhyan, Mahanadi-NEC and Andaman-Nicobar; the Kerala-Konkan-Lakshadweep basin is in Category III.','Category II has discoveries that are not yet produced commercially. Kerala-Konkan has no discovery so far. List as on the Ministry website, 2026; it can be revised.',null,true,2,2,1424) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f076','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Cambay Basin (Gujarat) is a narrow north-south intracratonic rift graben of Tertiary age floored by Deccan Traps; the Eocene Cambay Shale is its main source rock and Ankleshwar its best-known field.','Intracratonic rift = a crack that opened inside the continent. Thick shale in the sinking graben generated the oil.',null,true,3,1,1425) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f077','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Mumbai Offshore Basin is a pericratonic rift (passive margin) basin on the western shelf; Bombay High, discovered in 1974, produces mainly from Miocene limestone.','Pericratonic = at the edge of the craton. It formed when India rifted from Madagascar and Seychelles. Bombay High is India''s largest oil field.','Goa PSC Assistant Geologist 2021',true,3,1,1426) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f078','geological-assistant','geological-assistant-m4','Sedimentary basins of India','Digboi in the Assam-Arakan Basin (Upper Assam) had India''s first commercial oil well in 1889; the main reservoirs of Upper Assam are the Miocene Tipam Sandstone and the Oligocene Barail Group.','It is the oldest producing petroleum province of India. The basin has a shelf part (Upper Assam) and a fold belt part (Tripura, Cachar).',null,true,3,1,1427) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f079','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Krishna-Godavari Basin is a pericratonic rift basin on the east coast with Permian to Recent sediments; its deepwater block KG-D6 had a major gas discovery in 2002.','It formed when India separated from Antarctica and Australia. Ravva is its well-known offshore oil field.',null,true,2,2,1428) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f080','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Cauvery Basin is a pericratonic rift basin with horst-and-graben structure formed during the Late Jurassic-Early Cretaceous break-up of Gondwana; its Cretaceous rocks near Tiruchirappalli (Uttatur, Trichinopoly, Ariyalur) are richly fossiliferous.','Horst = raised block, graben = sunken block. The marine Cretaceous of Tiruchirappalli is a classic of Indian stratigraphy.',null,true,2,2,1429) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f081','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Rajasthan Basin has three sub-basins: Barmer-Sanchor (Mangala oil field, discovered 2004), Jaisalmer (gas) and Bikaner-Nagaur (heavy oil in Infracambrian rocks).','Barmer is a Tertiary rift like Cambay to its south. Mangala is the largest onland oil find in India in recent decades.',null,true,2,2,1430) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f082','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Kutch Basin is an east-west pericratonic rift basin famous for its marine Jurassic sequence (Patcham, Chari, Katrol, Umia) rich in ammonites.','The sea entered the rift in Jurassic time. It is the type area for the marine Jurassic of India.',null,true,2,2,1431) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f083','geological-assistant','geological-assistant-m4','Sedimentary basins of India','Kerala''s coastal Tertiary, oldest first: Alleppey beds (subsurface only), Vaikom beds, marine Miocene Quilon limestone, Warkalli Formation (Mio-Pliocene sandstone, clay, lignite). Vaikom is the oldest in the three-fold scheme.','These soft sediments rest on Precambrian crystalline rocks and form the main coastal aquifers of Kerala. Warkalli cliff at Varkala is the type area.','Kerala PSC Assistant Geologist 2025 (QP 26/2025/OL)',true,3,1,1432) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f084','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Vindhyan Basin is a large intracratonic Proterozoic (Purana) basin of central India with nearly undeformed Semri, Kaimur, Rewa and Bhander groups; Cuddapah, Chhattisgarh, Bhima and Kaladgi are other Purana basins.','Purana means ''ancient''. These basins sagged slowly inside the stable shield, so their beds stayed almost flat and unmetamorphosed.',null,true,2,2,1433) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f085','geological-assistant','geological-assistant-m4','Sedimentary basins of India','Gondwana basins are intracratonic rift (graben and half-graben) basins along the Damodar, Son-Mahanadi, Pranhita-Godavari and Satpura valleys, filled by Permian to Lower Cretaceous river and lake sediments that hold almost all of India''s coal.','They follow old weak zones in the shield. The fill starts with the glacial Talchir beds and then the coal-bearing Damuda Group.','UPSC Geologist Mains 2019 Geology Paper II',true,3,1,1434) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f086','geological-assistant','geological-assistant-m4','Sedimentary basins of India','Not all Indian basins are rifts: the Himalayan Foreland (Siwalik) and Ganga basins are foreland basins filled with molasse, and the Andaman-Nicobar Basin is a convergent-margin island-arc (forearc) basin.','A foreland basin forms where the plate bends down under the weight of a mountain belt. Molasse is the coarse debris shed from the rising mountains.','UPSC Geologist Mains 2019 Geology Paper II',true,2,2,1435) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f106','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Kerala-Konkan Basin is a passive-margin (pericratonic rift) basin off the south-west coast; the Vengurla Arch separates it from the Mumbai Offshore Basin to the north. It remains a Category III basin with no commercial discovery (DGH listing, 2024).','It formed when India rifted from Madagascar and the Seychelles. Thick Deccan basalt cover makes exploration below it difficult.',null,true,2,2,1436) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f107','geological-assistant','geological-assistant-m4','Sedimentary basins of India','Sedimentary basins are grouped by tectonic setting: rift and passive-margin basins (divergent), foreland, forearc and back-arc basins (convergent), pull-apart basins (strike-slip) and intracratonic sag basins.','The plate setting controls how a basin sinks, so it also controls its shape and its sediment fill.','UPSC Geologist Mains 2019 Geology Paper II',true,2,2,1437) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f108','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Narmada-Son-Tapti zone is regarded as a failed rift; Cambay and Narmada rifts cross in the Gulf of Khambhat, and Kutch, Cambay and Narmada rifts surround the Saurashtra horst.','A failed rift started to pull apart but never opened into an ocean. Kutch (Jurassic), Cambay (Early Cretaceous) and Narmada (Late Cretaceous) rifts opened one after another around the Saurashtra block.','Goa PSC Assistant Professor Geology 2021',false,2,2,1438) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u4c-f109','geological-assistant','geological-assistant-m4','Sedimentary basins of India','The Assam-Arakan Fold Belt (Tripura-Cachar-Mizoram) is a gas-rich belt of long anticlines; its main reservoirs are sandstones of the Miocene Surma Group (Bhuban and Bokabil formations).','Squeezing between India and Burma folded the Tertiary sediments into tight anticlines, which trap gas at their crests.',null,true,2,2,1439) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f001','geological-assistant','geological-assistant-m5','Origin of water: meteoric, juvenile, magmatic and sea waters','Meteoric water is water derived from the atmosphere as rain or snow; almost all usable groundwater is meteoric in origin.','It is part of the present-day hydrologic cycle. ''Meteoric'' comes from meteorology (weather), not from meteorites.','UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1440) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f002','geological-assistant','geological-assistant-m5','Origin of water: meteoric, juvenile, magmatic and sea waters','Connate water is water trapped in the pores of a sedimentary rock at the time of its deposition; it is usually very old and highly saline.','''Connate'' means ''born with'' the rock. It is often old sea water, so it is also called fossil water.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1441) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f003','geological-assistant','geological-assistant-m5','Origin of water: meteoric, juvenile, magmatic and sea waters','Juvenile water is new water from magma or the Earth''s deep interior that has never before been part of the hydrologic cycle.','''Juvenile'' means young or new. It is joining the surface water system for the first time.',null,true,3,1,1442) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f004','geological-assistant','geological-assistant-m5','Origin of water: meteoric, juvenile, magmatic and sea waters','Magmatic water is water derived from magma: it is called plutonic water when it separates at great depth and volcanic water when it separates at shallow depth.','Pluto = deep underworld, so plutonic = deep. Magmatic water may be juvenile or recycled, so the two words are not exact synonyms.','UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,2,2,1443) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f005','geological-assistant','geological-assistant-m5','Origin of water: meteoric, juvenile, magmatic and sea waters','Metamorphic water is water driven out of rocks during metamorphism, for example when hydrous (water-bearing) minerals break down.','Heat and pressure squeeze water out of minerals like clays and micas.',null,true,1,3,1444) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f006','geological-assistant','geological-assistant-m5','Origin of water: meteoric, juvenile, magmatic and sea waters','Sea (marine) water occurs in aquifers either by present-day intrusion along coasts or as old sea water trapped in marine sediments.','Intrusion is a modern process; trapped sea water is connate. Both make groundwater saline.',null,true,2,2,1445) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f007','geological-assistant','geological-assistant-m5','Hydrologic cycle','Oceans hold about 97% of Earth''s water; groundwater is only about 0.6% of the total, yet it is the largest store of liquid fresh water.','Most fresh water is locked in ice. Rivers and lakes together are far smaller than groundwater.',null,true,3,1,1446) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f008','geological-assistant','geological-assistant-m5','Hydrologic cycle','The hydrologic cycle is the endless circulation of water between ocean, atmosphere and land, driven by solar energy and gravity.','The Sun lifts water by evaporation; gravity brings it down as rain and moves it as runoff and groundwater.',null,true,3,1,1447) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f009','geological-assistant','geological-assistant-m5','Hydrologic cycle','The water balance (hydrologic) equation is: inflow - outflow = change in storage; for a basin, P = R + ET + change in storage.','It is simply conservation of mass. P = precipitation, R = runoff, ET = evapotranspiration.',null,true,3,1,1448) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f010','geological-assistant','geological-assistant-m5','Hydrologic cycle - precipitation','The Symons gauge is the standard non-recording rain gauge used in India; its collector is 127 mm in diameter.','Non-recording means it only stores rain; a person measures it once a day. 127 mm = 5 inches.',null,true,2,2,1449) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f011','geological-assistant','geological-assistant-m5','Hydrologic cycle - precipitation','Recording rain gauges are of three types: tipping-bucket, weighing-bucket and natural-siphon (float) type; they give rainfall intensity as well as amount.','They write a continuous record, so the time pattern of a storm is known.',null,true,2,2,1450) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f012','geological-assistant','geological-assistant-m5','Hydrologic cycle - precipitation','The arithmetic mean method of areal rainfall gives equal weight to all gauges and suits only flat areas with evenly spaced gauges.','A simple average ignores gaps between gauges and the effect of hills.',null,true,2,2,1451) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f013','geological-assistant','geological-assistant-m5','Hydrologic cycle - precipitation','In the Thiessen polygon method each rain gauge is weighted by the area of its polygon, drawn using perpendicular bisectors of lines joining adjacent gauges.','Every point in the basin is given the rainfall of its nearest gauge. Mean rain = sum(P x A) / sum(A).',null,true,3,1,1452) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f014','geological-assistant','geological-assistant-m5','Hydrologic cycle - precipitation','An isohyet is a line joining points of equal rainfall; the isohyetal method is the most accurate way to find mean areal rainfall, especially in hilly terrain.','The person drawing isohyets can use knowledge of hills (orographic effect), which polygons cannot.',null,true,3,1,1453) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f015','geological-assistant','geological-assistant-m5','Hydrologic cycle - precipitation','A hyetograph is a bar chart of rainfall intensity against time; a mass curve is a plot of cumulative rainfall against time.','Hyeto = rain. Do not confuse with hydrograph, which plots stream discharge.',null,true,3,1,1454) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f016','geological-assistant','geological-assistant-m5','Hydrologic cycle - precipitation','The double-mass curve is used to test the consistency of a rain gauge record and to correct it.','Cumulative rain at one station is plotted against the cumulative average of nearby stations. A break in slope shows a change at the station.',null,true,2,2,1455) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f017','geological-assistant','geological-assistant-m5','Hydrologic cycle - runoff','Stream flow is made of surface runoff (overland flow), interflow (shallow lateral flow through soil) and base flow (groundwater discharge).','Surface runoff and quick interflow form ''direct runoff''. Base flow is the slow, steady part.',null,true,3,1,1456) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f018','geological-assistant','geological-assistant-m5','Hydrologic cycle - infiltration','Infiltration is the entry of water through the soil surface; percolation is the further downward movement of that water toward the water table.','Infiltration is the ''gate''; percolation is the journey after the gate.',null,true,3,1,1457) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f019','geological-assistant','geological-assistant-m5','Hydrologic cycle - infiltration','Infiltration capacity is the maximum rate at which a soil can absorb water; Horton''s equation shows it falling exponentially with time to a constant value: f = fc + (f0 - fc)e^(-kt).','Dry soil drinks fast at first, then slows as pores fill and the surface seals. fc is the final steady rate.',null,true,3,1,1458) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f020','geological-assistant','geological-assistant-m5','Hydrologic cycle - infiltration','Infiltration is measured in the field with a double-ring infiltrometer; the outer ring stops water from the inner ring spreading sideways.','With the outer buffer ring flooded, flow under the inner ring is vertical, so the reading is true.',null,true,2,2,1459) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f021','geological-assistant','geological-assistant-m5','Hydrologic cycle - infiltration','The phi-index is the average rainfall intensity above which the volume of rainfall equals the volume of direct runoff.','It is a simple average loss rate. Rain above the phi line becomes runoff; rain below it is lost, mostly to infiltration.',null,true,2,2,1460) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f022','geological-assistant','geological-assistant-m5','Hydrologic cycle - evapotranspiration','Evapotranspiration is evaporation from soil and water plus transpiration from plants; potential evapotranspiration (PET) is its value when water supply is unlimited.','Actual ET can never exceed PET. The PET idea was introduced by Thornthwaite.',null,true,3,1,1461) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f023','geological-assistant','geological-assistant-m5','Hydrologic cycle - evapotranspiration','A lysimeter measures evapotranspiration directly: it is a tank of soil with plants in which all water inputs and outputs are measured.','ET = water added - water drained - change in soil moisture. A phytometer measures transpiration only.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1462) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f024','geological-assistant','geological-assistant-m5','Hydrologic cycle - evapotranspiration','The US Class A evaporation pan is about 1.2 m in diameter and 25 cm deep; lake evaporation = pan evaporation x pan coefficient (about 0.7).','A small metal pan heats up more than a lake, so it over-reads. The coefficient corrects this.',null,true,3,1,1463) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f025','geological-assistant','geological-assistant-m5','Hydrographs','A hydrograph is a graph of stream discharge (or stage) against time; a storm hydrograph has a rising limb, a peak (crest) and a recession (falling) limb.','The rising limb reflects the storm; the recession limb reflects water draining out of basin storage.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1464) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f026','geological-assistant','geological-assistant-m5','Hydrographs','Base flow is the groundwater contribution to a stream; it keeps perennial rivers flowing in dry weather and is separated from the hydrograph to get direct runoff.','Direct runoff hydrograph = total hydrograph - base flow.',null,true,3,1,1465) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f027','geological-assistant','geological-assistant-m5','Hydrographs','An effluent (gaining) stream receives groundwater because the water table is above stream level; an influent (losing) stream feeds the groundwater.','Effluent = groundwater flows out into the stream. Influent = stream water flows into the ground.','UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1466) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f028','geological-assistant','geological-assistant-m5','Hydrographs','A unit hydrograph is the direct runoff hydrograph produced by 1 cm of effective rainfall falling uniformly over the basin in a given duration; it was proposed by Sherman (1932).','Effective rainfall = rain that becomes direct runoff. The area under a unit hydrograph equals 1 cm depth over the basin.',null,true,3,1,1467) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f029','geological-assistant','geological-assistant-m5','Hydrographs','Unit hydrograph theory assumes linear response and time invariance, so ordinates are simply multiplied by the rainfall excess and hydrographs can be added.','Linear: double the rain excess, double every ordinate. Time-invariant: the same storm always gives the same hydrograph.',null,true,2,2,1468) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f030','geological-assistant','geological-assistant-m5','Subsurface movement and vertical distribution of groundwater','Subsurface water is divided into the zone of aeration (vadose zone) above and the zone of saturation (phreatic zone) below; the water table separates them.','In the vadose zone pores hold both air and water. Below the water table all pores are full of water.',null,true,3,1,1469) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f031','geological-assistant','geological-assistant-m5','Subsurface movement and vertical distribution of groundwater','The zone of aeration has three parts from top to bottom: soil-water zone, intermediate (vadose) zone and capillary fringe.','Roots use the top zone; the capillary fringe sits directly on the water table.',null,true,3,1,1470) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f032','geological-assistant','geological-assistant-m5','Subsurface movement and vertical distribution of groundwater','Soil water is of three kinds: hygroscopic water (held tightly on grains), capillary water (held by surface tension) and gravitational water (drains freely).','Plants can use only capillary water. Hygroscopic water is held too tightly; gravitational water drains away.',null,true,2,2,1471) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f033','geological-assistant','geological-assistant-m5','Subsurface movement and vertical distribution of groundwater','Field capacity is the water left in soil after gravity drainage; wilting point is the moisture at which plants wilt permanently; available water is the difference between them.','Above field capacity water drains away. Below wilting point roots cannot pull water out.',null,true,2,2,1472) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f034','geological-assistant','geological-assistant-m5','Subsurface movement and vertical distribution of groundwater','The capillary fringe is thicker in fine materials: capillary rise is inversely proportional to pore size, so it is highest in silt and clay and lowest in gravel.','Narrow tubes lift water higher. In gravel the rise is a few centimetres; in silt it can exceed a metre.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1473) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f035','geological-assistant','geological-assistant-m5','Subsurface movement and vertical distribution of groundwater','Pore-water pressure is less than atmospheric in the zone of aeration, equal to atmospheric at the water table and greater than atmospheric below it.','Above the water table water is held by suction (tension). This is why water does not flow into a hole dug in the vadose zone.',null,true,3,1,1474) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f036','geological-assistant','geological-assistant-m5','Subsurface movement and vertical distribution of groundwater','The water table is the upper surface of the zone of saturation in an unconfined aquifer; it generally follows the land surface as a subdued (gentler) replica.','It is high under hills and low under valleys, but with smaller relief than the ground.',null,true,3,1,1475) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f037','geological-assistant','geological-assistant-m5','Subsurface movement and vertical distribution of groundwater','The piezometric (potentiometric) surface is the imaginary surface to which water rises in wells tapping a confined aquifer.','It shows the pressure head of the confined water. If it lies above ground level, wells flow by themselves.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1476) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f038','geological-assistant','geological-assistant-m5','Subsurface movement and vertical distribution of groundwater','Groundwater moves from points of higher hydraulic head to lower head, from recharge areas (usually uplands) to discharge areas (valleys, springs, streams, sea).','Head = elevation + pressure head. Water follows total head, so it can even move upward in discharge areas.',null,true,3,1,1477) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f039','geological-assistant','geological-assistant-m5','Subsurface movement of groundwater - flow nets','A flow net is a set of flow lines and equipotential lines; in a homogeneous isotropic medium they cross at right angles and form curvilinear squares.','Equipotential = line of equal head. Water moves along flow lines, straight down the steepest head slope.',null,true,3,1,1478) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f040','geological-assistant','geological-assistant-m5','Subsurface movement of groundwater - flow nets','Seepage from a flow net: q = K x H x (nf / nd) per unit width, where nf = number of flow channels and nd = number of equipotential drops.','H is the total head loss. More flow channels mean more flow; more head drops mean a gentler gradient.',null,true,2,2,1479) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f041','geological-assistant','geological-assistant-m5','Subsurface movement of groundwater - flow nets','On a water table contour map groundwater flows at right angles to the contours toward lower head; closely spaced contours mean a steep gradient or low transmissivity.','Contours bending upstream at a river show a gaining (effluent) stream.',null,true,2,2,1480) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f042','geological-assistant','geological-assistant-m5','Springs','A spring is a concentrated natural discharge of groundwater at the land surface as flowing water; a seep (seepage area) is a slow, diffuse discharge.','Springs appear where the water table or a water-bearing opening meets the ground surface.','UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,2,2,1481) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f043','geological-assistant','geological-assistant-m5','Springs','A depression spring forms where the land surface dips down and cuts the water table.','The ground simply falls below the water level, so water flows out. Common in valleys.',null,true,3,1,1482) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f044','geological-assistant','geological-assistant-m5','Springs','A contact spring forms where a permeable water-bearing bed overlies a less permeable bed that is exposed at the surface.','Water cannot go down through the tight bed, so it moves sideways and comes out along the contact.',null,true,3,1,1483) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f045','geological-assistant','geological-assistant-m5','Springs','Artesian (fault) springs release confined water through a fault or the aquifer outcrop; tubular springs issue from solution channels or lava tubes and fracture springs from joints.','Todd''s gravity spring classes are: depression, contact, artesian, impervious-rock, and tubular or fracture springs.',null,true,2,2,1484) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f046','geological-assistant','geological-assistant-m5','Springs','A thermal spring discharges water warmer than the local mean annual air temperature; a geyser is a hot spring that erupts water and steam at intervals.','In a geyser, deep water becomes superheated; steam pressure builds and throws the water column out.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1485) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f047','geological-assistant','geological-assistant-m5','Springs','Meinzer classified springs by discharge into eight magnitudes; a first-magnitude spring discharges more than about 2.83 cubic metres per second (100 cubic feet per second).','First magnitude = biggest. Such springs are mostly in limestone (karst) and basalt.',null,true,2,2,1486) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f048','geological-assistant','geological-assistant-m5','Springs','The well-known cliff springs at Varkala (Papanasam), Kerala, emerge where permeable Warkalli sandstone and laterite rest on impermeable clay beds.','This is a contact spring: water moving down through sandstone is stopped by clay and comes out on the cliff face.',null,false,1,3,1487) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f049','geological-assistant','geological-assistant-m5','Classification of aquifers','An aquifer is a saturated formation that both stores water and transmits it in usable quantities to wells and springs, e.g. sand, gravel, sandstone, cavernous limestone.','Aqua = water, ferre = to bear. It needs both porosity and permeability.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1488) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f050','geological-assistant','geological-assistant-m5','Classification of aquifers','An aquiclude is a saturated formation that stores water but cannot transmit it at useful rates, e.g. clay.','Claudere = to shut. Clay is very porous but its pores are too tiny to let water move.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1489) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f051','geological-assistant','geological-assistant-m5','Classification of aquifers','An aquifuge is a formation that neither stores nor transmits water, e.g. massive unfractured granite or compact basalt.','Fugere = to drive away. It has no connected pores at all.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1490) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f052','geological-assistant','geological-assistant-m5','Classification of aquifers','An aquitard is a poorly permeable formation that transmits water slowly, enough for leakage between aquifers but not enough for wells, e.g. sandy clay.','Tardus = slow. It retards flow but does not stop it.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1491) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f053','geological-assistant','geological-assistant-m5','Classification of aquifers','An unconfined aquifer has the water table as its upper boundary; it is also called a water-table, phreatic or free aquifer.','Its top is open to the atmosphere through the pores above, so the water is at atmospheric pressure at the water table.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1492) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f054','geological-assistant','geological-assistant-m5','Classification of aquifers','A confined (artesian or pressure) aquifer is bounded above and below by impermeable beds and holds water under pressure greater than atmospheric; it is recharged mainly where it outcrops.','Because of the pressure, water in a well rises above the top of the aquifer.','UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1493) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f055','geological-assistant','geological-assistant-m5','Classification of aquifers','A leaky (semi-confined) aquifer is one whose confining bed is an aquitard, so water leaks into or out of it through that bed.','When it is pumped, part of the water comes as vertical leakage through the semi-permeable layer.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1494) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f056','geological-assistant','geological-assistant-m5','Classification of aquifers','A perched aquifer is a small saturated body held up above the main water table by a local impermeable lens, such as a clay layer.','The clay lens acts like a saucer. Wells in perched water give small, temporary yields.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1495) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f057','geological-assistant','geological-assistant-m5','Classification of aquifers','In an artesian well water rises above the top of the confined aquifer; it becomes a flowing artesian well when the piezometric surface is above ground level.','The name comes from Artois in France. No pumping is needed in a flowing well.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1496) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f058','geological-assistant','geological-assistant-m5','Classification of aquifers','A pumped confined aquifer stays fully saturated and releases water by compression of the aquifer and expansion of water; an unconfined aquifer releases water by gravity drainage of pores.','This is why confined storage coefficients are thousands of times smaller than unconfined ones.',null,true,3,1,1497) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f059','geological-assistant','geological-assistant-m5','Concepts of drainage basin and groundwater basin','A drainage basin (catchment or watershed) is the land area that drains to a common outlet; its boundary is the topographic divide.','All rain falling inside the divide leaves through one river mouth. It is the basic unit of surface hydrology.',null,true,3,1,1498) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f060','geological-assistant','geological-assistant-m5','Concepts of drainage basin and groundwater basin','A groundwater basin is a hydrogeologic unit containing one large aquifer or several connected aquifers; its boundary need not coincide with the surface drainage divide.','Underground boundaries are set by geology (faults, rock contacts) and by groundwater divides, not only by ridges.',null,true,3,1,1499) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f061','geological-assistant','geological-assistant-m5','Concepts of drainage basin and groundwater basin','A groundwater divide is a ridge in the water table from which groundwater flows away in opposite directions; no flow crosses it.','It is the underground twin of a watershed ridge, but it can shift when wells are pumped.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,2,2,1500) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f062','geological-assistant','geological-assistant-m5','Concepts of drainage basin and groundwater basin','Safe yield of a groundwater basin is the amount of water that can be withdrawn annually without producing an undesired result; withdrawal beyond it is overdraft.','Undesired results include falling water levels, sea water intrusion and land subsidence. Removing non-renewable storage is called groundwater mining.',null,true,2,2,1501) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f063','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - porosity','Porosity (n) is the volume of voids divided by the total volume of the rock, expressed as a percentage: n = (Vv / V) x 100.','It tells how much water a rock can hold, not how much it will yield.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1502) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f064','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - porosity','Primary porosity forms with the rock (intergranular pores, vesicles); secondary porosity develops later (joints, fractures, faults, solution cavities, weathering).','Hard rocks like granite and limestone depend on secondary porosity for their groundwater.',null,true,3,1,1503) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f065','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - porosity','Typical porosities: clay 45-55%, sand 30-40%, gravel 25-40%, sandstone 5-30%, fresh granite under 1-2%; clay has the highest porosity but very low permeability.','Clay has countless tiny pores that hold water tightly. High porosity does not mean a good aquifer.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1504) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f066','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - porosity','For equal spheres, cubic packing gives the maximum porosity (about 47.6%) and rhombohedral packing the minimum (about 26%), whatever the grain size.','Cubic = grains sit directly on top of each other (loosest). Rhombohedral = grains sit in the hollows (tightest).','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1505) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f067','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - porosity','Porosity of a sediment depends on sorting, packing and grain shape; well-sorted sediments are more porous than poorly sorted ones.','In poorly sorted sediment, small grains fill the gaps between big grains.',null,true,3,1,1506) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f068','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - porosity','Void ratio (e) is the volume of voids divided by the volume of solids; n = e / (1 + e) and e = n / (1 - n).','Porosity compares voids with the whole; void ratio compares voids with solids only. So e is always larger than n.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1507) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f069','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - porosity','Effective porosity is the share of interconnected pore space through which water can actually flow; pumice and vesicular basalt can have high total but low effective porosity.','Isolated bubbles hold water (or air) but are not linked, so they do not help flow.',null,true,3,1,1508) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f070','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - specific yield, specific retention','Specific yield (Sy) is the volume of water a saturated rock releases by gravity drainage, as a fraction of the total rock volume.','It is the usable part of the stored water. In coarse unconfined aquifers it is close to effective porosity.','UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1509) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f071','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - specific yield, specific retention','Specific retention (Sr) is the water held back against gravity as a fraction of total volume; porosity = specific yield + specific retention.','Water in the pores either drains (yield) or stays stuck to grains (retention). The two add up to all the pore water.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1510) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f072','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - specific yield, specific retention','Specific yield is highest in coarse sand and gravel (roughly 20-30%) and very low in clay (a few percent); specific retention increases as grain size decreases.','Fine grains have a huge surface area, so more water stays stuck to them.',null,true,3,1,1511) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f073','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - hydraulic conductivity','Intrinsic permeability (k) is a property of the rock alone; it has dimensions of area (m2) and is measured in darcy (1 darcy is about 0.987 x 10^-12 m2).','It depends on pore size and shape only, so it is the same for water, oil or gas.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1512) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f074','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - hydraulic conductivity','Hydraulic conductivity (K) depends on both the rock and the fluid: K = k x density x g / viscosity; it has units of velocity (m/day).','Warm water is less viscous, so K rises with temperature even though the rock is unchanged.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1513) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f075','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - hydraulic conductivity','Hydraulic conductivity falls sharply with grain size: gravel (hundreds of m/day) > sand (about 1-50 m/day) > silt > clay (far below 0.001 m/day).','Roughly, K is proportional to the square of grain diameter (Hazen: K = C x d10 squared).',null,true,3,1,1514) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f076','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - hydraulic conductivity','An aquifer is isotropic if K at a point is the same in all directions and homogeneous if K is the same at every point.','Isotropy is about direction; homogeneity is about place. Layered sediments are usually anisotropic, with horizontal K greater than vertical K.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1515) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f077','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - hydraulic conductivity','For layered beds, equivalent K for flow parallel to layers is the thickness-weighted arithmetic mean; for flow across layers it is the harmonic mean, which is always smaller.','Along the layers the best layer carries most flow. Across the layers the tightest layer controls the flow.',null,true,2,2,1516) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f078','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - transmissivity','Transmissivity (T) is hydraulic conductivity multiplied by saturated thickness: T = K x b; its unit is m2/day.','It is the flow through a unit width of the whole aquifer thickness under unit gradient. The term was introduced by Theis.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL); UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1517) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f079','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - storage coefficient','Storage coefficient (storativity, S) is the volume of water an aquifer releases per unit surface area per unit decline in head; it is dimensionless.','Volume released = S x area x drop in head. Volume / (area x length) has no units.','UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,3,1,1518) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f080','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - storage coefficient','Storativity of confined aquifers is very small, about 0.00005 to 0.005; in unconfined aquifers it equals specific yield, about 0.01 to 0.30.','Confined water comes only from squeezing; unconfined water comes from actually draining the pores.',null,true,3,1,1519) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f081','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - storage coefficient','Specific storage (Ss) is the water released per unit volume of aquifer per unit decline in head; its unit is 1/m and S = Ss x b.','Ss = density x g x (aquifer compressibility + porosity x water compressibility). Multiply by thickness b to get storativity.',null,true,2,2,1520) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f082','geological-assistant','geological-assistant-m5','Hydrological properties of rocks - storage coefficient','Hydraulic diffusivity is transmissivity divided by storativity (T/S = K/Ss); its unit is m2/day.','It tells how fast a change in head spreads through the aquifer. Confined aquifers (small S) respond very fast.',null,true,2,2,1521) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f083','geological-assistant','geological-assistant-m5','Water table fluctuations','Water level fluctuations are grouped as secular (over many years), seasonal (monsoon recharge and summer decline) and short-term (daily or shorter); a plot of well water level against time is a well hydrograph.','Secular trends show long-term over-use or climate change. Seasonal change shows yearly recharge.',null,true,2,2,1522) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f084','geological-assistant','geological-assistant-m5','Water table fluctuations','In most of India the water table is deepest just before the monsoon (April-May) and shallowest after it; CGWB measures levels four times a year: January, pre-monsoon, August and November.','Monsoon rain recharges the aquifer; summer pumping and natural drainage lower it again.',null,true,2,2,1523) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f085','geological-assistant','geological-assistant-m5','Water table fluctuations','A shallow water table can show a daily cycle caused by evapotranspiration: it falls during the day and recovers at night.','Phreatophytes (plants with roots reaching the water table) draw water in daylight. White''s method uses this cycle to estimate ET.','UPSC Geo-Scientist and Geologist Exam 2019 (Hydrogeology)',true,2,2,1524) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f086','geological-assistant','geological-assistant-m5','Water table fluctuations','In wells tapping confined aquifers, water level falls when atmospheric pressure rises; barometric efficiency = change in water level / change in atmospheric pressure head.','Air pushes directly on the water in the well, but the aquifer skeleton carries part of the load. Unconfined aquifers show almost no response.',null,true,3,1,1525) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f087','geological-assistant','geological-assistant-m5','Water table fluctuations','Tidal efficiency is the change in piezometric level divided by the change in tide level; in a confined aquifer, barometric efficiency + tidal efficiency = 1.','A rising tide loads the aquifer and raises the well level (direct relation). Barometric response is inverse.',null,true,3,1,1526) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f088','geological-assistant','geological-assistant-m5','Water table fluctuations','Earthquakes, passing trains and other external loads cause sudden short-lived water level changes in wells tapping confined aquifers.','The load squeezes the elastic aquifer and pushes pressure up for a moment. Earthquake-caused changes are called hydroseisms.',null,true,1,3,1527) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f089','geological-assistant','geological-assistant-m5','Water table fluctuations','Water table fluctuation method: recharge = specific yield x rise in water table x area.','The rise fills drained pores, and specific yield is the fraction of rock volume those pores make up.',null,true,3,1,1528) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f090','geological-assistant','geological-assistant-m5','Classification of aquifers (India)','About two-thirds of India is underlain by hard rocks (crystalline rocks, basalt and consolidated sediments), where groundwater occurs in the weathered zone and in fractures.','These rocks have almost no primary porosity, so yields are low and vary a lot from place to place.',null,true,3,1,1529) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f091','geological-assistant','geological-assistant-m5','Classification of aquifers (India)','The Indus-Ganga-Brahmaputra alluvium holds India''s most productive aquifers: thick sand and gravel beds forming multiple unconfined and confined aquifers tapped by tube wells.','Loose river sediments have high primary porosity and permeability, and recharge is large.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1530) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f092','geological-assistant','geological-assistant-m5','Classification of aquifers (India)','In Deccan Trap basalts groundwater occurs in weathered, vesicular and jointed parts of flows and in intertrappean beds; massive flow cores and red bole act as barriers.','Stacked lava flows give a layered system: each flow top can be a separate small aquifer.',null,true,3,1,1531) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f093','geological-assistant','geological-assistant-m5','Classification of aquifers (India)','Taylor (1959) divided India into eight groundwater provinces: Precambrian crystalline, Precambrian sedimentary, Gondwana sedimentary, Deccan trap, Cenozoic sedimentary, Cenozoic fault basin, Ganga-Brahmaputra alluvial and Himalayan highland.','The grouping follows rock type and age, because these control how water is stored. Kerala falls mainly in the Precambrian crystalline and Cenozoic sedimentary provinces.',null,true,3,1,1532) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f094','geological-assistant','geological-assistant-m5','Classification of aquifers (India)','The Cenozoic fault basin province of India covers the alluvium-filled rift valleys of the Narmada, Tapti and Purna rivers.','These are down-faulted troughs filled with thick, water-bearing alluvium inside hard-rock country.',null,true,2,2,1533) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f095','geological-assistant','geological-assistant-m5','Classification of aquifers (India)','At the Himalayan foothills the Bhabar is a coarse boulder-gravel belt with a deep water table; the Terai next to it has fine sediments, a spring line and flowing artesian wells.','Streams sink into the porous Bhabar and the water comes back up in the Terai under pressure.',null,true,3,1,1534) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f096','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','Most of Kerala is underlain by Archaean crystalline rocks (charnockite, khondalite, gneiss); sedimentary formations are limited to a narrow coastal belt.','About 88% of the state is hard rock and about 12% is coastal sediment (CGWB). So groundwater mostly sits in the weathered layer and fractures.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1535) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f097','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','Kerala has four main aquifer systems: weathered and fractured crystalline rocks, laterite, Tertiary sedimentary formations and coastal alluvium.','Going from the hills to the sea: crystallines (highland), laterite (midland), Tertiaries and alluvium (coast).',null,true,3,1,1536) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f098','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','The Tertiary formations of the Kerala coast, from oldest to youngest, are the Alleppey, Vaikom, Quilon and Warkalli beds.','Memory hook: A-V-Q-W, in alphabetical order from bottom to top.',null,true,3,1,1537) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f099','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','Among Kerala''s Tertiary aquifers, the Warkalli aquifer is the most extensively developed, while the Vaikom aquifer is regarded as the most potential.','Warkalli sands are shallower and easier to tap. Vaikom beds are thick, coarse sands and gravels at greater depth.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1538) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f100','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','Warkalli beds are sandstones and clays with lignite seams; Quilon beds are mainly fossiliferous limestone and clay and are a poor aquifer.','Sand layers give water; limestone-clay layers of the Quilon beds mostly act as confining layers.',null,true,2,2,1539) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f101','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','Laterite, which caps the midlands of Kerala, is a highly porous phreatic (water-table) aquifer tapped by open dug wells; it recharges quickly but also drains quickly.','Its many cavities let rain in fast, but water also escapes fast to valleys, so many laterite wells go dry in summer.',null,true,3,1,1540) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f102','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','In Kerala''s crystalline rocks, dug wells tap phreatic water in the weathered zone, while bore wells tap semi-confined to confined water in deeper fractures.','Fractures show up as lineaments on satellite images, so lineaments are the usual targets for bore well siting.',null,true,3,1,1541) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f103','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','Coastal alluvium (beach and river sands) forms a potential shallow phreatic aquifer along the Kerala coast, tapped by dug wells and filter-point wells.','Loose sand has good porosity and permeability. The risk here is salinity, since the sea and backwaters are close.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1542) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f104','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','Kerala gets about 3000 mm of rain a year, but steep slopes and 44 short rivers (41 west-flowing, 3 east-flowing) drain it quickly, so summer water scarcity is common.','High rainfall does not mean high recharge. Much water runs off to the sea within days.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1543) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f105','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','Kerala''s three physiographic zones are lowland (below 7.5 m above sea level), midland (7.5 to 75 m) and highland (above 75 m).','Each zone has its typical aquifer: alluvium and Tertiaries in the lowland, laterite in the midland, crystallines in the highland.',null,true,2,2,1544) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f106','geological-assistant','geological-assistant-m5','Classification of aquifers (Kerala)','Kerala PSC key: among Kerala''s crystalline rocks, charnockite is taken as the better aquifer; in reality yield depends on fractures and weathering, not rock type.','This was the keyed answer in a Kerala PSC paper. Yield really depends on how fractured and weathered the rock is at the site.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',false,1,3,1545) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f107','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','The Central Ground Water Board (CGWB) was formed in 1970 by renaming the Exploratory Tubewells Organisation (1954); its headquarters is at Faridabad, under the Ministry of Jal Shakti.','It is the national agency for groundwater surveys, monitoring and assessment. Its Kerala Region office is in Thiruvananthapuram.',null,true,3,1,1546) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f108','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','The Central Ground Water Authority (CGWA) was constituted in 1997 under the Environment (Protection) Act, 1986 to regulate and control groundwater development.','CGWB studies groundwater; CGWA regulates it (for example, permissions for extraction).',null,true,2,2,1547) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f109','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','In Kerala, groundwater is managed by the State Ground Water Department, and regulated under the Kerala Ground Water (Control and Regulation) Act, 2002 through the State Ground Water Authority.','The Act (Act 19 of 2002) allows areas to be notified and wells to be permitted and registered.',null,true,2,2,1548) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f110','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','India''s groundwater resources are estimated by the Groundwater Estimation Committee (GEC) methodology: first GEC-1984, revised as GEC-1997, and now GEC-2015.','CGWB and the State groundwater departments do the assessment jointly. It has been done every year since 2022.',null,true,3,1,1549) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f111','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','Stage of groundwater extraction (%) = (annual groundwater extraction / annual extractable groundwater resource) x 100.','It shows what share of the yearly usable recharge is being pumped out. Above 100% means pumping exceeds recharge.',null,true,3,1,1550) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f112','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','GEC-2015 categories by stage of extraction: safe up to 70%, semi-critical above 70% to 90%, critical above 90% to 100%, over-exploited above 100%.','Memory hook: 70-90-100. Units with poor quality water are separately tagged as saline.',null,true,3,1,1551) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f113','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','In GEC-2015, annual extractable groundwater resource = total annual recharge - natural discharges; recharge is estimated by the water table fluctuation and rainfall infiltration factor methods.','Some recharge must be left to feed streams and springs. The fluctuation method is used for the monsoon season.',null,true,2,2,1552) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f114','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','GEC-2015 recommends aquifer-wise assessment of both dynamic (annually replenished) and in-storage (static) groundwater; the unit is the watershed in hard-rock areas and the block/taluk in alluvial areas.','Dynamic resource = the yearly recharge in the fluctuation zone. In-storage resource = water below that zone.',null,true,2,2,1553) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f115','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','National assessment 2025: annual recharge 448.52 BCM, extraction 247.22 BCM, stage of extraction 60.63%; of 6762 units, 730 (10.8%) are over-exploited and 4946 (73.1%) are safe.','Annual extractable resource in 2025 is 407.75 BCM. Other units: 201 critical, 758 semi-critical and 127 saline. BCM = billion cubic metres.',null,true,2,2,1554) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f116','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','Kerala assessment 2024: of 152 blocks, 120 are safe, 29 semi-critical and 3 critical (Chittur and Malampuzha in Palakkad, and Kasaragod); none is over-exploited; stage of extraction is 53.78%.','Palakkad lies in the rain-shadow Palghat Gap with heavy irrigation pumping. Kasaragod has a long record of over-use for arecanut and coconut gardens.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,3,1,1555) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f117','geological-assistant','geological-assistant-m5','Groundwater basin - artificial recharge','Artificial recharge is the planned addition of surface water to an aquifer; methods are grouped as direct surface (spreading), direct subsurface (wells, shafts, pits) and indirect (induced recharge).','It speeds up natural infiltration, to store surplus monsoon runoff underground.',null,true,3,1,1556) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f118','geological-assistant','geological-assistant-m5','Groundwater basin - artificial recharge','Spreading methods (basins, ditch-and-furrow, flooding, percolation tanks, check dams) suit unconfined aquifers with permeable soil; injection (recharge) wells are needed for confined aquifers.','Spreading works only if water can soak straight down. A clay cover blocks it, so water must be put in through a well.',null,true,3,1,1557) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f119','geological-assistant','geological-assistant-m5','Groundwater basin - artificial recharge','The percolation tank, a surface pond built on permeable ground across a stream, is the most common artificial recharge structure in the hard-rock areas of India.','It holds monsoon runoff long enough for it to seep down into weathered and fractured rock.',null,true,3,1,1558) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f120','geological-assistant','geological-assistant-m5','Groundwater basin - artificial recharge','Induced recharge means pumping wells near a river or lake so that the lowered water table draws surface water into the aquifer.','The river bed acts as a natural filter. Collector wells and infiltration galleries on river banks use this idea.',null,true,2,2,1559) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f121','geological-assistant','geological-assistant-m5','Groundwater basin - artificial recharge','A subsurface dyke (underground dam) is an impermeable wall built below ground across a narrow valley to stop subsurface flow and store groundwater upstream.','Nothing is flooded and nothing evaporates. It suits the narrow valleys of Kerala''s midlands.',null,true,2,2,1560) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f122','geological-assistant','geological-assistant-m5','Groundwater basin - artificial recharge','Clogging by silt, air bubbles, bacteria and chemical precipitates is the main problem of recharge wells, so the recharge water must be clear and silt-free.','Fine particles block the pores around the well screen and cut the intake rate.',null,true,2,2,1561) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f123','geological-assistant','geological-assistant-m5','Groundwater basin - artificial recharge','Mazhapolima is a programme of Thrissur district, Kerala, that recharges open dug wells with rooftop rainwater.','Roof water is filtered and piped into the home well. It raises water levels and improves quality in summer.',null,false,1,3,1562) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f124','geological-assistant','geological-assistant-m5','Hydrographs','In straight-line base flow separation, direct runoff is taken to end N days after the peak, where N = 0.83 x A^0.2 and A is the drainage area in km2.','Bigger basins keep draining storm water for longer. Base flow is cut off the hydrograph so that only storm (direct) runoff is left.',null,true,2,2,1563) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f125','geological-assistant','geological-assistant-m5','Hydrographs','Time of concentration is the time water takes to travel from the farthest point of a basin to its outlet; basin lag is the time from the centre of effective rainfall to the hydrograph peak.','Both measure how fast a basin responds to rain. Small, steep basins have short lag and sharp flood peaks.',null,true,2,2,1564) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f126','geological-assistant','geological-assistant-m5','Hydrographs','The recession limb of a hydrograph follows Qt = Q0 x K^t, where K is the recession constant (less than 1); its shape depends on basin storage, not on the storm.','After rain stops the stream is fed only by water draining from storage, so discharge decays like a slowly emptying tank.',null,true,2,2,1565) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f127','geological-assistant','geological-assistant-m5','Hydrologic cycle - runoff','A perennial stream flows all year, an intermittent stream flows only in the wet season when the water table is high, and an ephemeral stream flows only just after rain.','Perennial streams are fed by base flow. Ephemeral streams always lie above the water table, so they lose water to the ground (influent).',null,true,2,2,1566) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f128','geological-assistant','geological-assistant-m5','Hydrologic cycle - evapotranspiration','Potential evapotranspiration is estimated by the Thornthwaite method (temperature based), the Blaney-Criddle method (temperature and daylight hours) and the Penman method (energy balance plus aerodynamic terms).','Penman needs the most data (radiation, wind, humidity) but has the strongest physical basis. The other two are simple empirical formulas.',null,true,2,2,1567) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f129','geological-assistant','geological-assistant-m5','Hydrologic cycle','Residence time of water in a reservoir = volume stored / rate of flow through it; it is about 9-10 days for the atmosphere but weeks to thousands of years for groundwater.','Groundwater is a large store with slow flow, so water stays long. This is why polluted aquifers take so long to clean up.','Kerala PSC Junior Hydrogeologist 2023 (88/2023/OL)',true,2,2,1568) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f130','geological-assistant','geological-assistant-m5','Springs','Bryan: gravity springs (depression, contact, artesian, impervious-rock, tubular or fracture springs) and non-gravitational springs (volcanic and fissure springs, usually thermal).','Gravity springs are driven by ordinary hydraulic head. Volcanic and fissure springs bring up deep, heated water.',null,true,2,2,1569) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u5a-f131','geological-assistant','geological-assistant-m5','Groundwater basin - resource assessment (CGWB, GEC-2015)','Kerala assessment 2024 (CGWB): total annual groundwater recharge 5.67 BCM, annual extractable resource 5.13 BCM and annual extraction 2.76 BCM.','Extraction is a little over half of the usable resource, which gives the stage of extraction of 53.78%. BCM = billion cubic metres.',null,true,1,3,1570) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
